def fastsam_letterbox(frame):
    h, w = frame.shape[:2]
    r = min(FASTSAM_IMGSZ / h, FASTSAM_IMGSZ / w)
    nw, nh = round(w * r), round(h * r)
    top = round((FASTSAM_IMGSZ - nh) / 2 - 0.1)
    left = round((FASTSAM_IMGSZ - nw) / 2 - 0.1)
    padded = cv2.copyMakeBorder(
        cv2.resize(frame, (nw, nh)), top, FASTSAM_IMGSZ - nh - top, left,
        FASTSAM_IMGSZ - nw - left, cv2.BORDER_CONSTANT, value=(114, 114, 114))
    return cv2.cvtColor(padded, cv2.COLOR_BGR2RGB), r, left, top


def build_fastsam_model():
    """Converts FastSAM to Core ML. Runs once, in its own process
    (this script with `--build-fastsam`), the first time the model is missing."""
    import ssl

    import certifi

    os.environ.setdefault("SSL_CERT_FILE", certifi.where())
    ssl._create_default_https_context = ssl.create_default_context

    import coremltools as ct
    import torch
    from ultralytics import FastSAM

    net = FastSAM(FASTSAM_WEIGHTS).model.eval().float().cpu().fuse()
    for m in net.modules():
        if hasattr(m, "export"):
            m.export = True
        if hasattr(m, "format"):
            m.format = "coreml"

    x = torch.rand(1, 3, FASTSAM_IMGSZ, FASTSAM_IMGSZ)
    with torch.no_grad():
        net(x)
        traced = torch.jit.trace(net, x, strict=False)
    ml = ct.convert(
        traced,
        inputs=[ct.ImageType("image", shape=x.shape, scale=1 / 255, bias=[0, 0, 0])],
        outputs=[ct.TensorType("preds"), ct.TensorType("protos")],
        convert_to="mlprogram",
        compute_precision=ct.precision.FLOAT16,
        minimum_deployment_target=ct.target.macOS13,
        skip_model_load=True,
    )
    os.makedirs(os.path.dirname(FASTSAM_MODEL_PATH), exist_ok=True)
    package = os.path.splitext(FASTSAM_MODEL_PATH)[0] + ".mlpackage"
    ml.save(package)
    ct.utils.compile_model(package, FASTSAM_MODEL_PATH)
    shutil.rmtree(package)
    print(f"Built {FASTSAM_MODEL_PATH}")


class FastSAMSegmenter:
    def __init__(self, conf, iou, max_area):
        import coremltools as ct

        if not os.path.exists(FASTSAM_MODEL_PATH):
            print("Converting FastSAM to Core ML (one time)...")
            subprocess.run([sys.executable, SCRIPT_PATH, FASTSAM_BUILD_FLAG],
                           check=True)
        self.model = ct.models.CompiledMLModel(
            FASTSAM_MODEL_PATH, compute_units=ct.ComputeUnit.ALL)
        self.conf, self.iou, self.max_area = conf, iou, max_area
        self.outline_letterboxed(np.zeros((FASTSAM_IMGSZ, FASTSAM_IMGSZ, 3), np.uint8),
                                 1.0, 0, 0, FASTSAM_IMGSZ, FASTSAM_IMGSZ)

    def outline_letterboxed(self, rgb, r, left, top, w, h, max_pixels=None,
                            conf=None, iou=None):
        """Returns one list of contours (screen pixels) per object. conf and iou,
        when given, override the starting values (Settings changes them live).
        """
        from PIL import Image

        conf = self.conf if conf is None else conf
        iou = self.iou if iou is None else iou
        out = self.model.predict({"image": Image.fromarray(rgb)})
        preds, protos = out["preds"][0], out["protos"][0]
        keep = preds[4] > conf
        cx, cy, bw, bh = preds[:4, keep]
        xywh = np.stack([cx - bw / 2, cy - bh / 2, bw, bh], 1)
        idx = np.array(cv2.dnn.NMSBoxes(xywh.tolist(), preds[4, keep].tolist(),
                                        conf, iou), dtype=int).flatten()[:300]
        if not len(idx):
            return []

        limit = max_pixels if max_pixels is not None else self.max_area * w * h
        regions = []
        selected = []
        for i, (x, y, bw_, bh_) in enumerate(xywh[idx]):
            x1, y1 = max(0, int((x - left) / r)), max(0, int((y - top) / r))
            x2 = min(w, int(np.ceil((x + bw_ - left) / r)))
            y2 = min(h, int(np.ceil((y + bh_ - top) / r)))
            if x2 <= x1 or y2 <= y1 or (x2 - x1) * (y2 - y1) > limit:
                continue
            selected.append(i)
            regions.append((x1, y1, x2, y2))
        if not selected:
            return []
        idx = idx[selected]

        n_proto, ph, pw = protos.shape
        logits = (preds[5:, keep].T[idx] @ protos.reshape(n_proto, -1)).reshape(
            len(idx), ph, pw).astype(np.float32)
        k = FASTSAM_IMGSZ / pw
        s = r / k
        objects = []
        for m, (x1, y1, x2, y2) in zip(logits, regions):
            M = np.float32([[s, 0, (x1 + 0.5) * s + left / k - 0.5],
                            [0, s, (y1 + 0.5) * s + top / k - 0.5]])
            patch = cv2.warpAffine(m, M, (x2 - x1, y2 - y1),
                                   flags=cv2.INTER_LINEAR | cv2.WARP_INVERSE_MAP)
            contours, _ = cv2.findContours((patch > 0).astype(np.uint8),
                                           cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            contours = [c + (x1, y1) for c in contours if cv2.contourArea(c) > 4]
            if contours:
                objects.append(contours)
        return objects


def fastsam_segmenter_process(conn, shm_name, conf, iou, max_area):
    try:
        shm = shared_memory.SharedMemory(name=shm_name, track=False)
    except TypeError:
        shm = shared_memory.SharedMemory(name=shm_name)
    rgb = np.ndarray((FASTSAM_IMGSZ, FASTSAM_IMGSZ, 3), np.uint8, buffer=shm.buf)
    try:
        segment = FastSAMSegmenter(conf, iou, max_area)
        conn.send("ready")
        while (msg := conn.recv()) is not None:
            conn.send(segment.outline_letterboxed(rgb, *msg))
    except (EOFError, BrokenPipeError, ConnectionResetError, KeyboardInterrupt):
        pass  # the app went away first: nothing left to outline for


def object_bbox(contours):
    xs = np.concatenate([c[:, 0, 0] for c in contours])
    ys = np.concatenate([c[:, 0, 1] for c in contours])
    return int(xs.min()), int(ys.min()), int(xs.max()), int(ys.max())


def object_area(contours):
    return sum(cv2.contourArea(c) for c in contours)


COMPONENT_INSIDE = 0.8      # ...and this much of its AREA lies inside that object's outline


def _inside_share(child, parent):
    """The share of `child`'s area that lies inside `parent`'s outline (both
    lists of contours). A box that merely CONTAINS a part says nothing about
    a part standing in a notch of its parent: a sleeve beside the planks
    that frame it is not a part of the planks."""
    x1, y1, x2, y2 = object_bbox(child)
    k = max(1, int(max(x2 - x1, y2 - y1) // 96))
    w, h = (x2 - x1) // k + 2, (y2 - y1) // k + 2
    cm = np.zeros((h, w), np.uint8)
    pm = np.zeros((h, w), np.uint8)
    cv2.drawContours(cm, [((c - (x1, y1)) // k).astype(np.int32) for c in child], -1, 1, -1)
    cv2.drawContours(pm, [((c - (x1, y1)) // k).astype(np.int32) for c in parent], -1, 1, -1)
    area = int(cm.sum())
    return 1.0 if area == 0 else float(np.count_nonzero(cm & pm)) / area


def find_parents(objects):
    """For each object, the index of the smallest bigger object it sits mostly
    inside (it's a part of that one: a logo, a button, a sticker), or None.
    Its box must lie inside the parent's box, and most of its area inside the
    parent's outline.
    """
    n = len(objects)
    boxes = [object_bbox(c) for c in objects]
    areas = [object_area(c) for c in objects]
    parents = [None] * n
    by_area = sorted(range(n), key=lambda j: (areas[j], j))
    for i in range(n):
        xi1, yi1, xi2, yi2 = boxes[i]
        box_area_i = max(1, (xi2 - xi1) * (yi2 - yi1))
        for j in by_area:
            if areas[i] >= areas[j]:
                continue
            xj1, yj1, xj2, yj2 = boxes[j]
            inter = max(0, min(xi2, xj2) - max(xi1, xj1)) * max(0, min(yi2, yj2) - max(yi1, yj1))
            if (inter / box_area_i >= COMPONENT_CONTAINMENT
                    and _inside_share(objects[i], objects[j]) >= COMPONENT_INSIDE):
                parents[i] = j
                break
    return parents


def box_iou(a, b):
    inter = max(0, min(a[2], b[2]) - max(a[0], b[0])) * max(0, min(a[3], b[3]) - max(a[1], b[1]))
    union = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - inter
    return inter / max(1, union)


def box_center(b):
    return (b[0] + b[2]) / 2, (b[1] + b[3]) / 2


def object_rect(contours):
    """(short side, long side, angle) of the object's tightest turned rectangle. The
    angle (degrees, modulo 90) is None when the object is too square or round for it
    to mean anything."""
    (_, _), (w, h), angle = cv2.minAreaRect(np.concatenate(contours))
    short, long = sorted((w, h))
    return short, long, (angle if long > 1.15 * max(short, 1) else None)


def object_centroid(contours):
    """The outline's centre of mass; unlike its box's centre, it turns with the object."""
    moments = [cv2.moments(c) for c in contours]
    a = sum(m["m00"] for m in moments)
    if a <= 0:
        return box_center(object_bbox(contours))
    return sum(m["m10"] for m in moments) / a, sum(m["m01"] for m in moments) / a


def object_color(frame, contours):
    """Mean BGR colour inside the outline, from every 4th pixel (plenty for a mean, and it
    runs on every detection)."""
    x1, y1, x2, y2 = object_bbox(contours)
    crop = np.ascontiguousarray(frame[y1:y2 + 1:4, x1:x2 + 1:4])
    mask = np.zeros(crop.shape[:2], np.uint8)
    cv2.drawContours(mask, [(c - (x1, y1)) // 4 for c in contours], -1, 255, -1)
    return cv2.mean(crop, mask)[:3]


def similar_color(a, b):
    """Loose on purpose, since an object moving into shadow darkens. What it rules out is
    a dark notebook's ID passing to the white desk left behind where it was (measured:
    brightness 58 vs 172; the notebook's own motion blur: 56)."""
    if a is None or b is None:
        return True
    la, lb = sum(a) / 3 + 1, sum(b) / 3 + 1
    if not 0.55 < la / lb < 1.8:
        return False
    if min(la, lb) < 60:
        return True
    return sum(abs(x / (3 * la) - y / (3 * lb)) for x, y in zip(a, b)) < 0.2


def rotate(v, degrees):
    a = np.radians(degrees)
    return v[0] * np.cos(a) - v[1] * np.sin(a), v[0] * np.sin(a) + v[1] * np.cos(a)


class ObjectTracker:
    """Gives each outlined object a stable ID from one detection to the next, so
    its name stays on it as it moves. Before matching, each object's last box is
    moved to where it should be now: a part (a logo on a notebook) to the same
    spot on its parent (turning with it), anything else onward at its last
    speed. Boxes then match by overlap, or failing that by centre distance. An
    object that drops out is still drawn for HOLD_S, then remembered unseen for
    MEMORY_S in case it comes back in the same place (a part: the same place on
    its parent), when it gets its old ID, and name, back.

    An object picked up and put down somewhere else, or moved further between two
    detections than any guess reaches, is matched by its size and shape instead:
    one lost object and one new object that look the same are taken to be the
    same, but only when neither could be anything else. Its parts then follow it.
    """

    MATCH_IOU = 0.3
    HOLD_S = 0.5
    MEMORY_S = 10.0
    MAX_COAST_S = 0.3
    MIN_RADIUS = 40
    FOUND_MIN_AREA = 2000
    YOUNG_S = 1.0
    SETTLED_HITS = 6

    def __init__(self):
        self.next_id = 1
        self.tracks = {}
        self.now = 0.0

    @staticmethod
    def _same_shape(area, sides, color, t):
        return (t["area"] >= ObjectTracker.FOUND_MIN_AREA and t["hits"] >= ObjectTracker.SETTLED_HITS
                and 0.75 < area / max(t["area"], 1) < 1.33 and similar_color(color, t["color"])
                and all(0.85 < a / max(b, 1) < 1.18 for a, b in zip(sides, t["sides"])))

    def visible(self):
        return {tid: t for tid, t in self.tracks.items() if self.now - t["seen"] <= self.HOLD_S}

    def _score(self, box, center, area, color, t, placed, now):
        """How well a detection fits a track, or None. `placed` holds the centre and
        angle of every track already matched this frame, so a part is looked for
        at its spot on its parent wherever the parent now is. Sizes are compared by
        outline area, which unlike a box's area doesn't grow when the object turns.
        """
        if not similar_color(color, t["color"]):
            return None
        dt = now - t["seen"]
        dormant = dt > self.HOLD_S
        tb, tc = t["box"], t["center"]
        guesses = []
        if t["parent"] in placed and t["rel"] is not None:
            (px, py), angle = placed[t["parent"]]
            rx, ry = rotate(t["rel"], angle)
            guesses.append(((px + rx, py + ry), True))
        if not dormant:
            coast = min(dt, self.MAX_COAST_S)
            guesses += [(tc, False), ((tc[0] + t["vel"][0] * coast, tc[1] + t["vel"][1] * coast), False)]
        elif t["parent"] is None:
            guesses.append((tc, False))
        size = max(tb[2] - tb[0], tb[3] - tb[1], 1)
        area_ratio = (area + 1) / (t["area"] + 1)
        reach = max(0.5 * size, self.MIN_RADIUS)
        best = None
        for (gx, gy), by_parent in guesses:
            dx, dy = gx - tc[0], gy - tc[1]
            iou = box_iou(box, (tb[0] + dx, tb[1] + dy, tb[2] + dx, tb[3] + dy))
            dist = np.hypot(center[0] - gx, center[1] - gy)
            if dormant:
                near = max(0.35 * size, 12)
                score = 2 - dist / near if dist < near and 0.67 < area_ratio < 1.5 else None
            elif by_parent:
                ok = (iou >= self.MATCH_IOU or dist < reach) and 0.5 < area_ratio < 2
                score = 2 + (iou + max(0.0, 1 - dist / reach)) / 2 if ok else None
            elif iou >= self.MATCH_IOU:
                score = 1 + iou
            elif dist < reach and 0.5 < area_ratio < 2:
                score = 1 - dist / reach
            else:
                score = None
            if score is not None and (best is None or score > best):
                best = score
        if best is not None and dormant:
            best -= 1
        if best is not None and t["hits"] >= self.SETTLED_HITS:
            best += 0.5
        return best

    def update(self, objects, parents, now, frame=None):
        """`parents` is find_parents(objects); `frame`, the picture they were found in,
        lets colours be compared too. Returns each object's ID."""
        n = len(objects)
        colors = [object_color(frame, c) if frame is not None else None for c in objects]
        boxes = [object_bbox(c) for c in objects]
        centers = [object_centroid(c) for c in objects]
        self.tracks = {tid: t for tid, t in self.tracks.items() if now - t["seen"] <= self.MEMORY_S}
        depth, root = [0] * n, list(range(n))
        for i in range(n):
            p, d = parents[i], 0
            while p is not None and d < n:
                root[i], p, d = p, parents[p], d + 1
            depth[i] = d
        rects = [object_rect(c) for c in objects]
        areas = [object_area(c) for c in objects]
        ids, angles = [None] * n, [0.0] * n
        taken, placed, found = set(), {}, set()
        for level in sorted(set(depth)):
            members = [i for i in range(n) if depth[i] == level]
            candidates = []
            for i in members:
                for tid, t in self.tracks.items():
                    if tid not in taken:
                        s = self._score(boxes[i], centers[i], areas[i], colors[i], t, placed, now)
                        if s is not None:
                            candidates.append((s, i, tid))
            for _, i, tid in sorted(candidates, reverse=True):
                if ids[i] is None and tid not in taken:
                    ids[i] = tid
                    taken.add(tid)
            pairs = []
            for i in members:
                young = ids[i] is not None and now - self.tracks[ids[i]]["born"] <= self.YOUNG_S
                if parents[i] is not None or (ids[i] is not None and not young):
                    continue
                for tid, t in self.tracks.items():
                    if (tid not in taken and t["parent"] is None and self._same_shape(areas[i], rects[i][:2], colors[i], t)
                            and (not young or t["seen"] < self.tracks[ids[i]]["born"])):
                        pairs.append((i, tid))
            for i, tid in pairs:
                if sum(p[0] == i for p in pairs) == 1 and sum(p[1] == tid for p in pairs) == 1:
                    taken.discard(ids[i])
                    ids[i] = tid
                    taken.add(tid)
                    found.add(i)
            for i in members:
                if ids[i] is None:
                    ids[i], self.next_id = self.next_id, self.next_id + 1
                old = self.tracks.get(ids[i])
                prev = old["angle"] if old else 0.0
                raw = rects[i][2]
                angles[i] = prev if raw is None else prev + ((raw - prev + 45) % 90 - 45)
                placed[ids[i]] = (centers[i], angles[i])
        for i in range(n):
            old = self.tracks.get(ids[i])
            vel = (0.0, 0.0)
            if old and self.HOLD_S >= now - old["seen"] > 0 and i not in found:
                oc, dt = old["center"], now - old["seen"]
                vel = ((centers[i][0] - oc[0]) / dt, (centers[i][1] - oc[1]) / dt)
            p, r = parents[i], root[i]
            if p is not None:
                parent = ids[r]
                rel = rotate((centers[i][0] - centers[r][0], centers[i][1] - centers[r][1]), -angles[r])
            else:
                parent, rel = (old["parent"], old["rel"]) if old else (None, None)
            points = np.concatenate([c[:, 0] for c in objects[i]])
            top = points[points[:, 1].argmin()]
            self.tracks[ids[i]] = {"box": boxes[i], "center": centers[i], "top": (int(top[0]), int(top[1])), "part": p is not None,
                                   "seen": now, "born": old["born"] if old else now, "hits": old["hits"] + 1 if old else 1,
                                   "vel": vel,
                                   "angle": angles[i], "sides": rects[i][:2], "area": areas[i], "color": colors[i],
                                   "parent": parent, "rel": rel}
        self.now = now
        return ids


def board_crop(frame, box):
    """The board's own pixels and where they start in the frame: Vision AI's
    region, which in HOS X is the grid box. (None, (0, 0)) for a box too small
    to look at."""
    h, w = frame.shape[:2]
    x0, y0, x1, y1 = box
    ix0, iy0 = max(0, int(round(x0))), max(0, int(round(y0)))
    ix1, iy1 = min(w, int(round(x1))), min(h, int(round(y1)))
    if ix1 - ix0 < 16 or iy1 - iy0 < 16:
        return None, (0, 0)
    return frame[iy0:iy1, ix0:ix1], (ix0, iy0)


def keep_on_board(objects, box):
    """Drops any object whose centre is off the board, and the board's own
    surface: it comes back as one shape covering most of the box (measured
    93% on the bench), which would otherwise make everything on it look like
    a part."""
    x0, y0, x1, y1 = box
    background = REGION_BACKGROUND_SHARE * max(1.0, (x1 - x0) * (y1 - y0))
    kept = []
    for contours in objects:
        bx1, by1, bx2, by2 = object_bbox(contours)
        cx, cy = (bx1 + bx2) / 2, (by1 + by2) / 2
        if x0 <= cx <= x1 and y0 <= cy <= y1 and object_area(contours) < background:
            kept.append(contours)
    return kept


def drop_tag_objects(objects, tag_pts):
    """Drops the AprilTag's own outline and the gripper mount it sits on.

    `tag_pts` is the tag's four corners in the same pixels as the outlines.
    An outline counts as the tag when it runs round the tag's centre and is
    no bigger than TAG_OBJECT_AREA_MULT tags, or when it lies inside the
    tag itself (its printed squares)."""
    if tag_pts is None:
        return objects
    pts = np.asarray(tag_pts, np.float32).reshape(-1, 2)
    if len(pts) < 3:
        return objects
    centre = (float(pts[:, 0].mean()), float(pts[:, 1].mean()))
    tag_area = max(1.0, float(cv2.contourArea(pts)))
    tx0, ty0 = pts.min(0)
    tx1, ty1 = pts.max(0)
    pad_x, pad_y = 0.25 * (tx1 - tx0), 0.25 * (ty1 - ty0)
    kept = []
    for contours in objects:
        x0, y0, x1, y1 = object_bbox(contours)
        inside_tag = (x0 >= tx0 - pad_x and y0 >= ty0 - pad_y
                      and x1 <= tx1 + pad_x and y1 <= ty1 + pad_y)
        around_tag = (object_area(contours) <= TAG_OBJECT_AREA_MULT * tag_area
                      and any(cv2.pointPolygonTest(c, centre, False) >= 0
                              for c in contours))
        if not (inside_tag or around_tag):
            kept.append(contours)
    return kept


def label_points(objects, parents):
    """A spot well inside each object for its number: the point farthest from its
    edge, ignoring the area its own parts cover, so a notebook's number doesn't
    land on its logo.
    """
    points = []
    for i, contours in enumerate(objects):
        x1, y1, x2, y2 = object_bbox(contours)
        mask = np.zeros((y2 - y1 + 1, x2 - x1 + 1), np.uint8)
        cv2.drawContours(mask, [c - (x1, y1) for c in contours], -1, 255, -1)
        for j, p in enumerate(parents):
            if p == i:
                cv2.drawContours(mask, [c - (x1, y1) for c in objects[j]], -1, 0, -1)
        dist = cv2.distanceTransform(mask, cv2.DIST_L2, 3)
        y, x = np.unravel_index(int(np.argmax(dist)), dist.shape)
        points.append((x1 + int(x), y1 + int(y)))
    return points


def naming_images(frame, objects, parents, box, is_part=None, max_side=None):
    """Two JPEGs of the same view, cropped to the board: the plain picture, and one
    with the objects to name outlined and numbered 1..n. The plain one matters: the
    outlines and numbers cover small parts, and the model names them better seeing both.
    `is_part` colours an object red even when the thing it's part of isn't being named.
    `max_side` (NAMER_MAX_SIDE when None) caps the photos' long side; outlines and
    numbers are drawn so they come out the same size however much the photo shrinks.
    """
    view = frame
    if box is not None:
        crop, _ = board_crop(frame, box)
        view = crop if crop is not None else frame
    scale = min(1.0, (max_side or NAMER_MAX_SIDE) / max(view.shape[:2]))
    k = 1.0 / scale
    line, fs, ft = max(2, round(2 * k)), 0.7 * k, max(2, round(2 * k))
    px, py, edge = round(4 * k), round(5 * k), max(1, round(k))
    marked = frame.copy()
    for j, (contours, p) in enumerate(zip(objects, parents)):
        part = is_part[j] if is_part is not None else p is not None
        cv2.drawContours(marked, contours, -1, (0, 0, 255) if part else (0, 255, 0), line)
    for n, (x, y) in enumerate(label_points(objects, parents), 1):
        (tw, th), _ = cv2.getTextSize(str(n), cv2.FONT_HERSHEY_SIMPLEX, fs, ft)
        cv2.rectangle(marked, (x - tw // 2 - px, y - th // 2 - py), (x + tw // 2 + px, y + th // 2 + py), (255, 255, 255), -1)
        cv2.rectangle(marked, (x - tw // 2 - px, y - th // 2 - py), (x + tw // 2 + px, y + th // 2 + py), (0, 0, 0), edge)
        cv2.putText(marked, str(n), (x - tw // 2, y + th // 2), cv2.FONT_HERSHEY_SIMPLEX, fs, (0, 0, 0), ft)
    images = []
    for img in (frame, marked):
        if box is not None:
            crop, _ = board_crop(img, box)
            img = crop if crop is not None else img
        if scale < 1:
            img = cv2.resize(img, None, fx=scale, fy=scale, interpolation=cv2.INTER_AREA)
        images.append(cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 90])[1].tobytes())
    return images


def naming_prompt(n, part_of, scene_hint, facts=()):
    """part_of[k] is what object k+1 is a part of (another number, or an object
    already named), or None. `facts` are outline_facts' lines for the numbers:
    each outline's measured size and colour.

    Vision AI's prompt, plus what the planner needs beyond a name: a colour and
    a few words of description to match the operator's words against, which
    outlines are the robot itself (never planned with), and whether a red
    outline is really a separate thing lying on the bigger one -- a sock in a
    bowl is picked up on its own; a mug's handle is not.
    """
    parts = "\n".join(f"- {k + 1} is a part of {p}" for k, p in enumerate(part_of) if p)
    measured = "\n".join(facts)
    return (
        f"These are two photos of the same board seen from above by a fixed camera. {scene_hint.strip()} "
        "The first photo is the plain view of the whole board. In the second, each outline to name is drawn "
        f"with a white label holding its number, from 1 to {n}. Red outlines are parts of a bigger object:\n"
        f"{parts or '- (none)'}\n\n"
        + (f"MEASURED BY HOS X (each number's outline as the vision system traced it, its size - a "
           f"turned one measured as itself):\n{measured}\n\n" if measured else "")
        + "The camera's colours can be off (a blue or grey cast over everything): judge what a thing "
        "is by its shape, texture and thickness, not its tint - a flat, stiff, matte sheet with straight "
        "edges is usually cardboard (give \"brown\" as its colour when its tint is only the cast).\n"
        + "Name what each number is with the short everyday name a person would use, 1-3 lowercase words "
        '(e.g. "notebook", "cloth", "usb cable", "screwdriver", "stepper motor") - the common word, not a '
        'rarer synonym ("cloth", not "fabric"). Name each number by what lies inside its OWN outline - look '
        "at exactly that patch in the plain photo: something lying on top of another object is named for "
        "what it is, not for the object under it. A green outline with red outlines inside it is the WHOLE "
        "object: name it for the whole thing (a dustpan whose tray is traced inside it is the \"dustpan\"), "
        "even when its number sits on one end of it - the red outlines are its parts, each named on its own. "
        "Check the name against the measured size: a 1 in strip at a book's edge is its tab or band, not a "
        'cable. For a part, name the part itself ("logo", "lettering", "sticker", "button", "handle", "lid"), '
        "not the thing it is on. Be specific only when you are sure: when you can't tell exactly what "
        "something is, use the plain general word a person would (a scattering of small bits you can't "
        'identify is "debris") rather than a specific guess. Name only what you can see: never use a name '
        "because it appears in these instructions. Only when the board really holds a "
        "dustpan or a brush, name their pieces this way: a dustpan's hollow inside is its \"tray\", its front "
        "edge its \"lip\", a brush's or broom's brush end its \"bristles\".\n\n"
        "THE ROBOT is in view too: its aluminium frame, steel rods, lead screw, stepper motors, belts, the "
        "carriage block riding on the rods and the gripper under it - and everything fixed to the carriage "
        "or the gripper: sponge or foam pads on the jaws, wires, connectors, small circuit boards, zip ties, "
        "brackets. A number on any of these is the robot, named for what it is (\"gripper\", \"sponge "
        'pad", "wires", "carriage"): follow it in the plain photo to what it is fixed to. Things lying loose '
        "on the board are not the robot, whatever they look like.\n\n"
        "If a number marks bare surface (the table, floor, board, grid, cutting mat or wood grain around the "
        'objects), a shadow, a reflection or a gap, name it "surface". If it is a person\'s hand, arm or '
        'fingers (holding or touching something), name it "hand". If it is a real object you can\'t identify, '
        'use "unknown".\n\n'
        "For every number also give:\n"
        '- "color": its main colour in one word ("black", "white", "silver", ...);\n'
        '- "desc": a useful visual description in 12-30 words covering material, shape, surface or texture, '
        "markings, condition, orientation and visible boundaries or distinctive details; "
        "include every clearly visible feature, not just a generic category. Be concrete "
        "and prioritize what distinguishes this exact item: overall shape, apparent material, "
        "color, texture or markings, orientation, condition, and whether its visible edges "
        "are straight, rounded, irregular, folded, chipped or partly hidden. Mention its "
        "approximate size relative to nearby objects when clear; do not invent measurements "
        "or details hidden from view. Prefer \"small, round, red plastic lid; scuffed surface, "
        "raised rim, lying flat\" over \"red lid\", and \"long, narrow, silver metal tool "
        "with a flat end, angled from upper left to lower right\" over \"metal tool\". "
        "If a feature is uncertain, omit it rather than guess;\n"
        '- "robot": true when it is the robot\'s own machinery or anything fixed to it (frame, rails, lead '
        "screws, rods, motors, belts, pulleys, carriage, gripper, the pads on its jaws, its wires, connectors "
        "and circuit boards); false for anything lying loose on the board, whatever it looks like - when "
        "unsure, false;\n"
        '- "loose": only for a red-outlined part - true when it is a separate thing, or a piece of one, '
        "lying on or in the bigger object that could be lifted off on its own (a sock in a bowl, a pen on "
        "a book, a hand brush lying in a dustpan - its handle and its bristles alike), false when it is "
        "attached to the bigger object or printed on it (a handle, a lid, a button, a logo);\n"
        '- "thing": when the number is only a PIECE of a bigger thing whose other pieces carry other '
        "numbers (a stapler's top and base, a toy car's body and wheels; a brush's handle and its bristles), "
        'the everyday name of that WHOLE thing ("stapler", "toy car", "hand brush") - the same words for EVERY '
        "piece of it, its biggest piece and its handle included, and for a loose red-outlined piece too; "
        '"" only when the number is a whole thing by itself or a part of the bigger object it is drawn on.\n\n'
        "Do not guess or return coordinates: HOS X derives each outline's complete board-cell footprint "
        "from its measured polygon. Describe only details visibly supported by the photos.\n"
        'Reply with JSON only: {"objects": [{"n": 1, "name": "...", "color": "...", "desc": "...", '
        '"robot": false, "loose": false, "thing": ""}, ...]}, one entry for every number.'
    )


def parse_naming_reply(text, n):
    """{number: {"name", "color", "desc", "robot", "loose"}} for every number
    the reply named; "unknown" and numbers out of range are left out."""
    if "{" not in text:
        raise ValueError(f"no JSON in the reply: {text[:60]!r}")
    data = json.loads(text[text.index("{"):text.rindex("}") + 1])
    entries = data.get("objects", []) if isinstance(data, dict) else []
    names = {}
    for item in entries if isinstance(entries, list) else []:
        if not isinstance(item, dict):
            continue
        try:
            num = int(item.get("n", 0))
        except (TypeError, ValueError):
            continue
        name = str(item.get("name", "")).strip().lower()
        if 1 <= num <= n and name and name != "unknown":
            names[num] = {"name": name,
                          "color": str(item.get("color") or "").strip().lower(),
                          "desc": str(item.get("desc") or "").strip(),
                          "robot": item.get("robot") is True,
                          "loose": item.get("loose") is True,
                          "thing": str(item.get("thing") or "").strip().lower()}
    return names


def ask_for_names(model, images, prompt, n):
    """One vision call; returns parse_naming_reply's {number: entry}. With a
    supporting view camera, its side view goes last (user, 2026-10-18: "see
    the object from all sides before naming")."""
    client = make_client()
    side = support_image_part()
    extra = []
    if side is not None:
        extra = [{"type": "text", "text":
                  "LAST IMAGE: a SIDE VIEW of the same board from the supporting "
                  "view camera, taken now -- a low, close look across the board, "
                  "often much closer and sharper than the top-down images. It "
                  "has no numbers or outlines. First match each object it shows "
                  "to its numbered outline (by colour, size, shape and where it "
                  "sits), then NAME THAT OBJECT FROM THE SIDE VIEW: its texture, "
                  "material, thickness and 3D shape there decide what it is, over "
                  "a guess from the flat top view (lighting in either view does "
                  "not change what an object is). The close-up is evidence, not a "
                  "guess: when it shows which KIND of thing an object is, give "
                  "that specific kind as the name, not only its category word. "
                  "Say in its desc what the side "
                  "view showed. Objects the side view does not show are named "
                  "from the board images as usual. Name only the numbered "
                  "outlines of the board images."}, side]
    text = call_model(client, model=model, max_tokens=NAMER_MAX_TOKENS,
                      stage="Naming", priority=PRIORITY_NAMING,
                      reasoning=NAMER_REASONING,
                      messages=[{"role": "user", "content": [
                          {"type": "text", "text": prompt},
                          *({"type": "image_url", "image_url": {
                              "url": "data:image/jpeg;base64," + base64.b64encode(jpeg).decode(),
                              "detail": "high"}} for jpeg in images),
                          *extra,
                      ]}])
    return parse_naming_reply(text, n)


RECALL_IOU = 0.5           # the same place: the boxes overlap this much,
RECALL_AREA = (0.67, 1.5)  # and the outline is about as big


def outline_traits(snap):
    """What a task compares the snapshot's outlines by, per outline: box,
    centre, area, sides (short, long), mean colour, the parent's index, and
    a part's distance from its parent's centre -- which, unlike an offset,
    stays the same when the robot turns the object it moves."""
    frame, objects = snap.get("frame"), snap["objects"]
    parents = snap.get("parents") or find_parents(objects)
    centres = [object_centroid(c) for c in objects]
    out = []
    for i, contours in enumerate(objects):
        short, long, _ = object_rect(contours)
        p = parents[i]
        out.append({
            "box": object_bbox(contours), "center": centres[i],
            "area": object_area(contours), "sides": (short, long),
            "color": (object_color(frame, contours)
                      if frame is not None else None),
            "parent": p,
            "dist": (None if p is None else float(np.hypot(
                centres[i][0] - centres[p][0], centres[i][1] - centres[p][1])))})
    return out


def _same_place(a, b):
    """One thing that has not moved: the boxes overlap and the size and
    colour agree -- the tracker's own test for an object that comes back
    where it was."""
    ratio = (a["area"] + 1) / (b["area"] + 1)
    return (box_iou(a["box"], b["box"]) >= RECALL_IOU
            and RECALL_AREA[0] < ratio < RECALL_AREA[1]
            and similar_color(a["color"], b["color"]))


def _same_look(a, b):
    """One thing put down somewhere else: ObjectTracker._same_shape's test --
    big enough to tell apart, with the same area, sides and colour."""
    return (min(a["area"], b["area"]) >= ObjectTracker.FOUND_MIN_AREA
            and 0.75 < a["area"] / max(b["area"], 1) < 1.33
            and all(0.85 < x / max(y, 1) < 1.18
                    for x, y in zip(a["sides"], b["sides"]))
            and similar_color(a["color"], b["color"]))


def _same_part(a, b, parent_size):
    """One part of an object that moved with it: as far from the object's
    centre as before, about as big, the same colour."""
    ratio = (a["area"] + 1) / (b["area"] + 1)
    return (abs(a["dist"] - b["dist"]) < max(0.2 * parent_size, 12)
            and 0.5 < ratio < 2 and similar_color(a["color"], b["color"]))


def _unique_pairs(pairs):
    """The pairs (a, b) in which neither a nor b has any other partner."""
    return [(a, b) for a, b in pairs
            if sum(q[0] == a for q in pairs) == 1
            and sum(q[1] == b for q in pairs) == 1]


def recall_outlines(snap, todo, seen):
    """Which of the snapshot's outlines `todo` (indices of outlines with no
    answer yet) are things seen before under another ID: {index: old ID}.

    `seen` is {old ID: traits, its parent as an ID} for everything a task
    has seen and had an answer for, as it was last seen. Only IDs that are
    not on the board now can match, each at most once:
    1. the same place -- covered for a while (the gripper sat over it) or
       an outline that flickered, and the tracker gave it a fresh ID;
    2. the same look somewhere else -- the robot picked it up and put it
       down, and nothing else on the board, or remembered, looks like it;
    3. a part of an object known now (by 1 or 2, or one the tracker never
       lost), as far from the object's centre as before.
    Whatever is left over is new on the board."""
    ids = snap["ids"]
    on_board = set(ids)
    free = {tid: t for tid, t in seen.items() if tid not in on_board}
    if not todo or not free:
        return {}
    traits = outline_traits(snap)
    found = {}
    pairs = sorted(((box_iou(traits[i]["box"], t["box"]), i, tid)
                    for i in todo for tid, t in free.items()
                    if _same_place(traits[i], t)), reverse=True)
    for _, i, tid in pairs:
        if i not in found and tid not in found.values():
            found[i] = tid

    def gone():
        return {tid: t for tid, t in free.items() if tid not in found.values()}

    for i, tid in _unique_pairs([
            (i, tid) for i in todo if i not in found
            for tid, t in gone().items() if _same_look(traits[i], t)]):
        found[i] = tid

    def depth(i):
        d, p = 0, traits[i]["parent"]
        while p is not None and d < len(traits):
            d, p = d + 1, traits[p]["parent"]
        return d

    parts = [i for i in todo if i not in found and traits[i]["parent"] is not None]
    for level in sorted({depth(i) for i in parts}):
        pairs = []
        for i in parts:
            if i in found or depth(i) != level:
                continue
            p = traits[i]["parent"]
            box = traits[p]["box"]
            size = max(box[2] - box[0], box[3] - box[1], 1)
            owner = found.get(p, ids[p])
            pairs += [(i, tid) for tid, t in gone().items()
                      if t["parent"] == owner and t["dist"] is not None
                      and _same_part(traits[i], t, size)]
        for i, tid in _unique_pairs(pairs):
            found[i] = tid
    return found


class PendingTask:
    """One task waiting while Vision AI is still running.

    The newest task replaces the one waiting. Nothing is started here: the
    frame loop takes it once Vision AI is idle and no planner job is running.
    """

    def __init__(self):
        self.item = None

    def hold(self, task, ask, repeat, vision_running) -> bool:
        """True when `task` has to wait. A task given with Vision AI idle
        is not stored."""
        if not vision_running:
            return False
        self.item = {"task": task, "ask": bool(ask), "repeat": bool(repeat)}
        return True

    def take(self, vision_running, planner_running):
        """The waiting task, once Vision AI and the planner are both idle."""
        if self.item is None or vision_running or planner_running:
            return None
        item, self.item = self.item, None
        return item


def naming_ahead_open(state, runner_active, sim_active) -> bool:
    """Vision AI may name the board on its own, once, before the first task.

    A task already given closes it. A task waiting, a planner job, a Vision
    AI sequence, or the robot moving also owns the board."""
    if getattr(state, "ahead_naming_closed", False):
        return False
    pending = getattr(state, "pending_task", None)
    if pending is not None and getattr(pending, "item", None) is not None:
        return False
    if getattr(state, "dseq", None) is not None:
        return False
    job = getattr(state, "ai_job", None)
    if job is not None and not getattr(job, "done", True):
        return False
    return not runner_active and not sim_active


class ObjectNamer:
    """Names the outlined objects with a vision model in a background thread, so
    the video never waits. Every call asks only about objects without a name;
    the named ones are left alone.

    Naming starts on its own once, before the first task, so the names are
    already on the video when that task is typed. That pass does not run
    again: the first task closes it, whether or not the call is still in
    flight (the task waits for the one call, then uses those names). From
    the second task on, S1 renames outlines it still recognises and Vision
    AI names only the ones S1 could not -- when that task runs, not while
    the board sits idle before it. The N key names again on demand. An
    object the tracker lost and found again under a fresh ID gets back the
    answer it had (recall). While a task is being planned, or the robot is
    moving, this stays quiet.
    """

    MESSAGE_S = 6

    def __init__(self):
        self.names = {}
        self.info = {}
        self.asked = set()
        self.busy = False
        self.message, self.message_until = "", 0.0
        self._lock = threading.Lock()
        self._idle = threading.Event()
        self._idle.set()
        # {ID: traits} of every answered outline a task has seen, as last
        # seen, and the frame size they are measured in.
        self.seen = {}
        self._seen_shape = None
        # {track ID: time.time() it was first seen unanswered} so a flicker
        # is not named, and when the same failed set may be sent again.
        self._seen_since = {}
        self._wake_at = 0.0
        self._retry_after = 0.0
        self._retry_key = None
        self._missing_key = False
        # {track id: s1_outline_feats} of named outlines, for the rename
        # on the second task and after.
        self.s1 = {}
        # The one before-task naming call. `ahead_closed` is set when the
        # first task is given, so a failed call is not retried after that.
        self.ahead_started = False
        self.ahead_closed = False

    def recall(self, snap):
        """Gives each outline with no answer that is something a task saw
        before -- the tracker gave it a fresh ID -- the answer it had (see
        recall_outlines). Returns {new ID: old ID}."""
        ids = snap["ids"]
        frame = snap.get("frame")
        parents = snap.get("parents") or find_parents(snap["objects"])
        with self._lock:
            seen = (dict(self.seen) if frame is not None
                    and self._seen_shape == frame.shape[:2] else {})
        todo = [i for i, tid in enumerate(ids)
                if tid not in self.names and tid not in self.asked]
        carried = {}
        for i, old in sorted(recall_outlines(snap, todo, seen).items()):
            new = ids[i]
            info = dict(self.info.get(old) or {})
            if seen[old]["parent"] is None and parents[i] is not None:
                # It stood on its own before and now lies on or in something
                # (a sock dropped in a bowl): a loose thing, not a part.
                info["loose"] = True
            if info:
                self.info[new] = info
            if old in self.names:
                self.names[new] = self.names[old]
            self.asked.add(new)
            carried[new] = old
        return carried

    def remember(self, snap, replaced=()):
        """Keeps how every answered outline in `snap` looks, for the next
        task's recall(). Things not on the board now are kept as they were
        last seen: covered or lifted, they may come back. `replaced` are old
        IDs whose things now carry a new one."""
        ids = snap["ids"]
        frame = snap.get("frame")
        if frame is None:
            return
        traits = outline_traits(snap)
        now = {}
        for i, tid in enumerate(ids):
            if tid in self.names or tid in self.asked:
                t = dict(traits[i])
                t["parent"] = None if t["parent"] is None else ids[t["parent"]]
                now[tid] = t
        with self._lock:
            if self._seen_shape != frame.shape[:2]:
                self.seen, self._seen_shape = {}, frame.shape[:2]
                self.s1 = {}
            for old in replaced:
                self.seen.pop(old, None)
                self.s1.pop(old, None)
            # An old ID for something on the board now under another one
            # would be a second "it" to recall.
            for tid in [tid for tid, t in self.seen.items() if tid not in now
                        and any(_same_place(t, n) for n in now.values())]:
                del self.seen[tid]
            self.seen.update(now)
        try:
            self._keep_s1(snap)
        except Exception as e:
            print(f"[vision] could not keep S1 features: {e}")

    def _keep_s1(self, snap):
        """Each named outline's colour and shape, for s1_rename later."""
        frame = snap.get("frame")
        if frame is None or not snap.get("objects") or not snap.get("box"):
            return
        fh, fw = frame.shape[:2]
        grid = Grid(fw, fh, list(snap["box"]), square_cells=False)
        ids = snap.get("ids") or []
        for i, tid in enumerate(ids):
            if tid not in self.names:
                continue
            feat = s1_outline_feats(snap, i, grid)
            if feat:
                feat["at"] = feat["c"]
                self.s1[tid] = feat

    def say(self, text):
        self.message, self.message_until = text, time.time() + self.MESSAGE_S

    def current_message(self):
        return self.message if time.time() < self.message_until else ""

    def start(self, frame, objects, ids, box):
        """The N key: names every unnamed object now."""
        if self.busy:
            return
        if not objects:
            self.say("No objects to name")
            return
        pending = [i for i, tid in enumerate(ids) if tid not in self.names]
        if not pending:
            self.say("All objects already named")
            return
        snap = {"frame": frame, "objects": objects, "ids": list(ids),
                "box": box}
        self._launch(frame, objects, ids, pending, box, remember_snap=snap)

    def name_ahead(self, snap, force=False):
        """Name outlines that still have no answer, without waiting.

        Called with each new look at the board before the first task, so
        the names are on the video when it is given. One call: after it
        has been started, a later look does not start another (a failed
        call may be retried until the first task closes this). An outline
        is sent only once it has kept its ID for NAME_AHEAD_SETTLE_S,
        unless `force` (the first task arrived before the outlines had
        settled). An outline already answered -- including one the model
        called unknown -- is not sent again. A call already running is
        left alone. Returns True when a call was started.
        """
        if self.ahead_closed:
            return False
        if self.ahead_started and not self._retry_key:
            return False
        if snap is None or self.busy or not snap.get("objects"):
            return False
        now = time.time()
        carried = self.recall(snap)
        ids = list(snap.get("ids") or [])
        pending = [i for i, tid in enumerate(ids)
                   if tid not in self.names and tid not in self.asked]
        self.remember(snap, carried.values())
        pending_ids = {ids[i] for i in pending}
        self._seen_since = {tid: t for tid, t in self._seen_since.items()
                            if tid in pending_ids}
        for tid in pending_ids:
            self._seen_since.setdefault(tid, now)
        if not pending:
            self._wake_at = now + 3600.0
            return False
        if force:
            ready = list(pending)
        else:
            ready = [i for i in pending
                     if now - self._seen_since[ids[i]] >= NAME_AHEAD_SETTLE_S]
        if not ready:
            self._wake_at = (min(self._seen_since[ids[i]] for i in pending)
                             + NAME_AHEAD_SETTLE_S)
            return False
        key = tuple(ids[i] for i in ready)
        if now < self._retry_after and key == self._retry_key:
            self._wake_at = self._retry_after
            return False
        if not resolve_api_key():
            if not self._missing_key:
                self._missing_key = True
                self.say("No OpenAI API key - put it in openai.txt next to HOS X")
            self._wake_at = now + NAME_RETRY_S
            return False
        held = {"frame": snap.get("frame"), "objects": snap.get("objects"),
                "ids": ids, "box": snap.get("box"),
                "parents": snap.get("parents")}
        print(f"[vision] naming {len(ready)} object(s) before a task")
        self._wake_at = now + 3600.0
        started = self._launch(snap["frame"], snap["objects"], ids, ready,
                               snap["box"], remember_snap=held)
        if started:
            self.ahead_started = True
        return started

    def unanswered(self, ids):
        """The IDs the model has not answered for yet -- neither named nor
        already called "unknown" (a shadow, a gap, bare board)."""
        return [tid for tid in ids
                if tid not in self.names and tid not in self.asked]

    def name_now(self, frame, objects, ids, box):
        """For a task: names every object the model has not answered for
        yet before it returns. Waits for a call already in flight first,
        since that one may be naming the same objects. Returns "" or why
        naming failed.

        An outline the model already called "unknown" is NOT asked about
        again: it never gets a name, so counting it as unnamed made every
        single task pay a full naming round trip for the same shadow."""
        deadline = time.time() + 2 * (API_TIMEOUT_S * API_RETRIES + 30)
        while time.time() < deadline:
            pending = [i for i, tid in enumerate(ids)
                       if tid not in self.names and tid not in self.asked]
            if not pending:
                return ""
            if not self._claim():
                self._idle.wait(timeout=1.0)
                continue
            job = self._prepare(frame, objects, ids, pending, box)
            if job is None:
                self._release()
                return self.current_message() or "Naming could not start."
            return self._run(*job)
        return "Naming did not finish in time."

    def _claim(self):
        with self._lock:
            if self.busy:
                return False
            self.busy = True
            self._idle.clear()
            return True

    def _release(self):
        with self._lock:
            self.busy = False
            self._idle.set()

    def _launch(self, frame, objects, ids, pending, box, remember_snap=None):
        """Start one naming call. False when a call is already running, or
        this one could not be prepared. `remember_snap` is kept so a name
        given here can be recalled if the tracker renumbers the outline
        before the next task."""
        if not self._claim():
            return False
        try:
            job = self._prepare(frame, objects, ids, pending, box)
        except Exception as e:
            self._retry_after = time.time() + NAME_RETRY_S
            self._retry_key = tuple(ids[i] for i in pending)
            self._release()
            self.say(f"Naming failed: {str(e)[:90]}")
            return False
        if job is None:
            self._retry_after = time.time() + NAME_RETRY_S
            self._retry_key = tuple(ids[i] for i in pending)
            self._release()
            return False
        self.say(f"Naming {len(pending)} object"
                 f"{'s' if len(pending) != 1 else ''}...")
        threading.Thread(target=self._run, args=(*job, remember_snap),
                         daemon=True).start()
        return True

    def _prepare(self, frame, objects, ids, pending, box):
        """(images, prompt, ids, model) for one call, or None without a key."""
        if not resolve_api_key():
            self.say("No OpenAI API key - put it in openai.txt next to HOS X")
            return None
        full = find_parents(objects)
        part_of = []
        for i in pending:
            p = full[i]
            if p is None:
                part_of.append(None)
            elif p in pending:
                part_of.append(str(pending.index(p) + 1))
            elif ids[p] in self.names:
                part_of.append(f'the "{self.names[ids[p]]}" (already named)')
            else:
                part_of.append("a bigger object")
        sub_parents = [pending.index(full[i]) if full[i] in pending else None for i in pending]
        images = naming_images(frame, [objects[i] for i in pending], sub_parents, box,
                               is_part=[full[i] is not None for i in pending])
        try:
            facts = outline_facts({"frame": frame, "objects": objects,
                                   "box": box}, pending, colour=False)
        except Exception as e:
            print(f"[vision] no measured sizes for naming: {e}")
            facts = []
        return (images, naming_prompt(len(pending), part_of, VISION_SCENE_HINT,
                                      facts),
                [ids[i] for i in pending], NAMER_MODEL)

    def _run(self, images, prompt, ids, model, remember_snap=None):
        error = ""
        try:
            got = ask_for_names(model, images, prompt, len(ids))
            for n, entry in got.items():
                tid = ids[n - 1]
                self.info[tid] = {k: entry.get(k, "") for k in
                                  ("color", "desc", "robot", "loose", "thing")}
                self.names[tid] = entry["name"]
            self.asked.update(ids)
            if remember_snap is not None:
                try:
                    self.remember(remember_snap)
                except Exception as e:
                    print(f"[vision] could not keep the new names for recall: {e}")
            self._retry_after = 0.0
            self._retry_key = None
            self.say(f"Named {len(got)} of {len(ids)} new object{'s' if len(ids) > 1 else ''}")
            named = ", ".join(self.names[ids[n - 1]] for n in sorted(got))
            print(f"[vision] named {len(got)} of {len(ids)}: {named or 'nothing'}")
        except Exception as e:
            error = f"Naming failed: {str(e)[:90]}"
            self._retry_after = time.time() + NAME_RETRY_S
            self._retry_key = tuple(ids)
            self.say(error)
            print(f"[vision] {error}")
        finally:
            self._release()
        return error


class LiveVision:
    """Vision AI's camera loop, without its window: FastSAM in its own process,
    the newest board frame handed over the moment each result returns, and
    the tracker and namer run on that feeder thread. The frame loop only
    submits frames and draws the last result; a task takes a snapshot of it.
    """

    def __init__(self):
        self.tracker = ObjectTracker()
        self.namer = ObjectNamer()
        self.ready = False
        self.failed = ""
        self.rate = 0.0
        self._lock = threading.Lock()
        self._pending_changed = threading.Condition(self._lock)
        self._stop = threading.Event()
        self._pending, self._pending_id = None, 0
        self._view = None
        self._results = 0
        self._proc = self._conn = self._shm = self._thread = None
        self._started = 0.0

    def start(self):
        if not os.path.exists(FASTSAM_MODEL_PATH) and not os.path.exists(FASTSAM_WEIGHTS):
            self.failed = (f"Vision AI is off: FastSAM was not found in "
                           f"{VISION_AI_DIR} (FastSAM-s.pt or its .coreml_cache).")
            print(f"[vision] {self.failed}")
            return self
        self._started = time.time()
        try:
            self._shm = shared_memory.SharedMemory(create=True, size=FASTSAM_IMGSZ * FASTSAM_IMGSZ * 3)
            ctx = multiprocessing.get_context("spawn")
            self._conn, child_conn = ctx.Pipe()
            self._proc = ctx.Process(target=fastsam_segmenter_process, daemon=True,
                                     args=(child_conn, self._shm.name, VISION_CONF,
                                           VISION_IOU, VISION_MAX_AREA))
            self._proc.start()
            child_conn.close()
        except Exception as e:
            self.failed = f"Vision AI could not start: {e}"
            print(f"[vision] {self.failed}")
            self._close_shm()
            return self
        self._thread = threading.Thread(target=self._feed, daemon=True)
        self._thread.start()
        return self

    def submit(self, frame, box, tag_pts=None, region=None, adjust=None):
        """Offer the newest camera frame, the grid box and the AprilTag's
        corners, all in that frame's pixels. Never blocks: a frame arriving
        while one is being outlined just replaces the one waiting.

        `adjust`, a CameraSettings, is applied on this object's own thread
        to the frame it takes: the box and corners are then in the adjusted
        frame's pixels. The UI thread no longer makes a full-size adjusted
        frame for every camera frame when this thread takes one in three.

        `region` is the part of the board FastSAM may look at -- the
        reachable cells, see reachable_box(). None means the whole box;
        NO_REACH means nothing is reachable, so nothing is outlined."""
        if frame is None or self._thread is None:
            return
        region = (None if region is None else
                  tuple(float(v) for v in region))
        with self._pending_changed:
            self._pending = (frame, tuple(float(v) for v in box), tag_pts,
                             region, adjust)
            self._pending_id += 1
            self._pending_changed.notify()

    def _feed(self):
        try:
            if self._conn.recv() != "ready":
                return
            print(f"[vision] FastSAM ready in {time.time() - self._started:.1f} s")
            self.ready = True
            sent_id, last, sent_at = 0, None, 0.0
            while not self._stop.is_set():
                with self._pending_changed:
                    while (not self._stop.is_set()
                           and (self._pending is None
                                or self._pending_id == sent_id)):
                        self._pending_changed.wait()
                    if self._stop.is_set():
                        break
                    pending, pending_id = self._pending, self._pending_id
                # FastSAM flat out (~20-30 outlines a second) kept a core and
                # the GPU busy and this thread's tracking holding the GIL the
                # frame loop needs -- clicks paid for outlines nobody can see
                # change that fast. VISION_MAX_FPS is plenty to follow a
                # moving object.
                wait = sent_at + 1.0 / max(1.0, VISION_MAX_FPS) - time.time()
                if wait > 0:
                    with self._pending_changed:
                        if (not self._stop.is_set()
                                and self._pending_id == pending_id):
                            self._pending_changed.wait(wait)
                    continue
                sent_id = pending_id
                sent_at = time.time()
                frame, box, tag_pts, region, adjust = pending
                if adjust is not None:
                    frame = adjust.apply(frame)
                area = box if region is None else region
                if region == NO_REACH:
                    crop = None
                else:
                    crop, (ox, oy) = board_crop(frame, area)
                if crop is None:
                    objects = []
                else:
                    rgb, r, left, top = fastsam_letterbox(crop)
                    np.ndarray(rgb.shape, np.uint8, buffer=self._shm.buf)[:] = rgb
                    self._conn.send((r, left, top, crop.shape[1], crop.shape[0],
                                     VISION_MAX_AREA * frame.shape[0] * frame.shape[1],
                                     VISION_CONF, VISION_IOU))
                    objects = self._conn.recv()
                    objects = [[c + (ox, oy) for c in contours]
                               for contours in objects]
                    objects = drop_tag_objects(keep_on_board(objects, area),
                                               tag_pts)
                parents = find_parents(objects)
                now = time.time()
                ids = self.tracker.update(objects, parents, now, frame)
                labels = [(tid, t["top"], t["part"])
                          for tid, t in self.tracker.visible().items()]
                with self._lock:
                    self._view = {"frame": frame, "box": box, "objects": objects,
                                  "ids": ids, "parents": parents, "labels": labels,
                                  "time": now,
                                  "region": None if region == NO_REACH else area}
                    self._results += 1
                    if last:
                        rate = 1 / max(1e-6, now - last)
                        self.rate = 0.8 * self.rate + 0.2 * rate if self.rate else rate
                last = now
        except (EOFError, OSError):
            if not self._stop.is_set():
                self.failed = "Vision AI's outliner stopped (see the console)."
                print(f"[vision] {self.failed}")
        except Exception as e:
            self.failed = f"Vision AI stopped: {e}"
            print(f"[vision] {self.failed}")

    def view(self):
        """The last result: {"frame", "box", "objects", "ids", "parents",
        "labels", "time"} in camera pixels, or None before the first one."""
        with self._lock:
            return self._view

    def status(self):
        if self.failed:
            return "off"
        if not self.ready:
            return "loading FastSAM..."
        view = self.view()
        count = len(view["objects"]) if view else 0
        return f"{count} objects  {self.rate:.0f} updates/s"

    def name_now(self):
        """The N key: name every unnamed object on the board now."""
        view = self.view()
        if view is None:
            self.namer.say("Wait for the outlines to appear first")
            return
        self.namer.start(view["frame"], view["objects"], view["ids"],
                         view["box"])

    def snapshot(self, timeout=VISION_READY_WAIT_S, on_wait=None):
        """The last result, for a task -- waiting up to `timeout` for the
        first one while FastSAM loads. Raises ModelError if there is none."""
        deadline = time.time() + timeout
        while True:
            if self.failed:
                raise ModelError(self.failed)
            view = self.view()
            if view is not None:
                return dict(view)
            if time.time() >= deadline:
                raise ModelError("Vision AI has not outlined the board yet - "
                                 "is the camera on and the grid box over the board?")
            if on_wait:
                on_wait()
            time.sleep(0.1)

    def _close_shm(self):
        if self._shm is not None:
            try:
                self._shm.close()
                self._shm.unlink()
            except Exception:
                pass
            self._shm = None

    def stop(self):
        self._stop.set()
        with self._pending_changed:
            self._pending_changed.notify_all()
        if self._proc is not None and self._proc.pid is not None:
            self._proc.terminate()
            self._proc.join(timeout=2)
        if self._thread is not None:
            self._thread.join(timeout=2)
        self._close_shm()


_LIVE_SCALED = [None, None, None]


def draw_live_vision(frame, view, names, info, scale):
    """Vision AI's overlay on the video: green outlines, red for parts, each
    name centred just above its object's highest point. `scale` takes the
    camera pixels the outlines are in to the video's own. Robot parts the
    namer recognised are drawn grey: seen, but never planned with."""
    if not view:
        return frame
    parents = view["parents"]
    cached = _LIVE_SCALED
    if cached[0] is not view or cached[1] != scale:
        # Outlines change only when vision does (~10 times a second); the
        # window redraws up to 60. Scale each result's contours once.
        cached[:] = [view, scale,
                     [[(c * scale).astype(np.int32) for c in contours]
                      for contours in view["objects"]]]
    for scaled, tid, p in zip(cached[2], view["ids"], parents):
        meta = info.get(tid) or {}
        if is_surface_name(names.get(tid) or ""):
            continue        # bare board, mat, grid, shadow: not an object
        if meta.get("robot"):
            color = (150, 150, 150)
        elif p is not None and VISION_MARK_PARTS and not meta.get("loose"):
            color = (0, 0, 255)
        else:
            color = (0, 255, 0)
        cv2.drawContours(frame, scaled, -1, color, VISION_OUTLINE_PX,
                         cv2.LINE_AA)
    if not VISION_SHOW_NAMES:
        return frame
    h, w = frame.shape[:2]
    placed = []
    for tid, (x, y), part in sorted(view["labels"], key=lambda e: e[1][1]):
        name = names.get(tid)
        if not name or is_surface_name(name):
            continue
        meta = info.get(tid) or {}
        (tw, th), base = cv2.getTextSize(name, cv2.FONT_HERSHEY_SIMPLEX, NAME_FONT, 2)
        x, y = int(x * scale), int(y * scale)
        tx = max(3, min(x - tw // 2, w - tw - 4))
        ty = y - 8 if y - th - 12 > 0 else y + th + 12
        for _ in range(4):
            box = (tx - 3, ty - th - 4, tx + tw + 3, ty + base + 1)
            if not any(box[0] < b[2] and b[0] < box[2] and box[1] < b[3] and b[1] < box[3] for b in placed):
                break
            ty -= th + base + 6
        ty = min(max(ty, th + 5), h - base - 2)
        box = (tx - 3, ty - th - 4, tx + tw + 3, ty + base + 1)
        placed.append(box)
        if meta.get("robot"):
            color = (170, 170, 170)
        elif part and VISION_MARK_PARTS and not meta.get("loose"):
            color = (0, 0, 255)
        else:
            color = (0, 255, 0)
        cv2.rectangle(frame, box[:2], box[2:], (0, 0, 0), -1)
        cv2.putText(frame, name, (tx, ty), cv2.FONT_HERSHEY_SIMPLEX, NAME_FONT, color, 2)
    return frame


def colour_word(bgr) -> str:
    """A colour name for a mean BGR value -- the fallback when the naming
    model gave none."""
    if bgr is None:
        return "?"
    px = np.uint8([[[int(max(0, min(255, v))) for v in bgr[:3]]]])
    hue, sat, val = (int(v) for v in cv2.cvtColor(px, cv2.COLOR_BGR2HSV)[0, 0])
    hue *= 2
    if val < 50:
        return "black"
    if sat < 45:
        return "white" if val > 190 else "gray"
    if hue < 15 or hue >= 345:
        return "red" if val > 110 else "brown"
    if hue < 40:
        return "orange" if val > 150 else "brown"
    if hue < 70:
        return "yellow"
    if hue < 165:
        return "green"
    if hue < 260:
        return "blue"
    if hue < 290:
        return "purple"
    return "pink"


def outline_polygon(contours, grid: Grid):
    """An object's outline as HOS X's polygon: (col, row) points in grid units,
    from its largest contour, simplified to a few dozen vertices -- enough
    to follow the shape, few enough for polygon_to_cells to stay quick."""
    c = max(contours, key=cv2.contourArea)
    if len(c) < 3:
        return None
    eps = max(1.5, 0.005 * cv2.arcLength(c, True))
    approx = cv2.approxPolyDP(c, eps, True).reshape(-1, 2)
    if len(approx) < 3:
        approx = c.reshape(-1, 2)
    poly = [grid.pixel_to_grid(float(x), float(y)) for x, y in approx]
    return poly if _poly_area(poly) > 1e-6 else None


THING_JOIN_PAD = 0.02   # pieces of one thing may lie this far apart (of the frame)
THING_SEAM = 0.08       # ...and must share this much of the smaller one's edge
# Names that are only ever a piece of something: one of these, untagged,
# joins the single thing whose pieces it touches.
THING_PIECE_WORDS = frozenset((
    "handle", "head", "grip", "neck", "shaft", "stick", "pole", "bristles",
    "bristle", "brush head", "lip", "edge", "rim", "base", "floor", "wall",
    "tray", "body", "blade", "connector", "collar", "ring", "cap"))


def thing_groups(keys, objects, thing_of, frame_shape=None, name_of=None,
                 doubtful=None):
    """[(thing, [indices])]: the outlines in `keys` the namer called pieces of
    one thing (the same thing_of(i)) whose boxes meet, two or more each. An
    outline NAMED for a thing that other pieces belong to (the namer called
    the brush's main piece "hand brush", its bristles a piece of "hand
    brush") is that thing's main body and joins them. Two separate dustpans
    on one board stay two: their pieces do not touch. Pieces join only along
    a shared seam (seam_share, THING_SEAM); the body on any contact.
    `doubtful`, a set, gets the pieces that touch their thing without sharing
    a seam with it."""
    pad = THING_JOIN_PAD * max(frame_shape[:2]) if frame_shape else 20.0
    by_thing = {}
    bodies = set()
    for i in keys:
        t = str(thing_of(i) or "").strip().lower()
        if t:
            by_thing.setdefault(t, []).append(i)
    if name_of is not None:
        loose = []
        for i in keys:
            if str(thing_of(i) or "").strip():
                continue
            n = str(name_of(i) or "").strip().lower()
            if n in by_thing:
                by_thing[n].append(i)       # named for the thing: its body
                bodies.add(i)
                continue
            # "brush head" is a piece of "brush" whatever its tag says
            hit = [t for t in by_thing if re.search(rf"(?<!\w){re.escape(t)}(?!\w)", n)]
            if len(hit) == 1:
                by_thing[hit[0]].append(i)
            elif n in THING_PIECE_WORDS:
                loose.append(i)
        # a bare piece word ("handle") joins the one thing whose pieces it touches
        for i in loose:
            bi = object_bbox(objects[i])
            near = [t for t, idx in by_thing.items() if any(
                bi[0] - pad <= object_bbox(objects[j])[2]
                and object_bbox(objects[j])[0] - pad <= bi[2]
                and bi[1] - pad <= object_bbox(objects[j])[3]
                and object_bbox(objects[j])[1] - pad <= bi[3] for j in idx)]
            if len(near) == 1:
                by_thing[near[0]].append(i)
    groups = []
    for thing, idx in by_thing.items():
        boxes = {i: object_bbox(objects[i]) for i in idx}
        root = {i: i for i in idx}

        def find(i):
            while root[i] != i:
                root[i] = root[root[i]]
                i = root[i]
            return i

        for a in idx:
            for b in idx:
                if a < b:
                    ba, bb = boxes[a], boxes[b]
                    if not (ba[0] - pad <= bb[2] and bb[0] - pad <= ba[2]
                            and ba[1] - pad <= bb[3] and bb[1] - pad <= ba[3]):
                        continue
                    seam = seam_share(objects[a], objects[b])
                    if seam >= THING_SEAM or (seam > 0 and (a in bodies or b in bodies)):
                        root[find(a)] = find(b)
        sets = {}
        for i in idx:
            sets.setdefault(find(i), []).append(i)
        joined = [m for m in sets.values() if len(m) > 1]
        groups += [(thing, sorted(m)) for m in joined]
        if doubtful is not None:
            for m in sets.values():
                if len(m) == 1 and any(seam_share(objects[m[0]], objects[j]) > 0
                                       for g in joined for j in g):
                    doubtful.add(m[0])
    return groups


def seam_share(a, b):
    """How much of the smaller of two outlines' edges runs along the other:
    0 for outlines apart, ~1 for one wrapped round the other. Pieces of one
    thing share seams; a floor line crossing under a tool only touches it."""
    pts = np.concatenate([c.reshape(-1, 2) for c in list(a) + list(b)])
    x0, y0 = (pts.min(0) - 6).astype(int)
    x1, y1 = (pts.max(0) + 6).astype(int)
    shape = (y1 - y0 + 1, x1 - x0 + 1)
    ma, mb = np.zeros(shape, np.uint8), np.zeros(shape, np.uint8)
    cv2.drawContours(ma, [(c - (x0, y0)).astype(np.int32) for c in a], -1, 255, -1)
    cv2.drawContours(mb, [(c - (x0, y0)).astype(np.int32) for c in b], -1, 255, -1)
    touch = np.count_nonzero(cv2.bitwise_and(cv2.dilate(ma, np.ones((9, 9), np.uint8)), mb))
    edge = min(sum(cv2.arcLength(c, True) for c in a),
               sum(cv2.arcLength(c, True) for c in b))
    # the 9 px dilation lays a band ~4.5 px deep along the shared edge
    return touch / 4.5 / max(1.0, edge)


LIP_WORDS_RE = re.compile(r"(?<!\w)(lip|edge|blade|mouth|opening)(?!\w)")


def compass(dx, dy):
    """'up', 'down-right', ... for a step of (dx, dy) grid units (rows go down)."""
    names = ("right", "up-right", "up", "up-left", "left", "down-left",
             "down", "down-right")
    return names[int(((math.degrees(math.atan2(-dy, dx)) % 360) + 22.5) // 45) % 8]


TRAY_WORDS_RE = re.compile(
    r"(?<!\w)(tray|pan|scoop|inside|interior|floor|base|basin|bowl|hollow)(?!\w)")
LIP_EDGE_MIN = 0.42     # a lip runs along its object's outer edge for this much,
LIP_EDGE_SURE = 0.6     # and from this much on it outranks the tray
TRAY_MIN_SHARE = 0.25   # a tray covers at least this much of its object


def edge_share(part, whole):
    """How much of `part`'s outline runs along `whole`'s outer edge, 0..1.
    A dustpan's real lip IS its edge; a brush lying across the pan, named
    "lip" by mistake, is inside it."""
    pts = np.concatenate([c.reshape(-1, 2) for c in list(part) + list(whole)])
    x0, y0 = (pts.min(0) - 8).astype(int)
    x1, y1 = (pts.max(0) + 8).astype(int)
    shape = (y1 - y0 + 1, x1 - x0 + 1)
    band, line = np.zeros(shape, np.uint8), np.zeros(shape, np.uint8)
    cv2.drawContours(band, [(c - (x0, y0)).astype(np.int32) for c in whole], -1, 255, 9)
    cv2.drawContours(line, [(c - (x0, y0)).astype(np.int32) for c in part], -1, 255, 1)
    total = np.count_nonzero(line)
    return np.count_nonzero(cv2.bitwise_and(band, line)) / float(max(1, total))


MOUTH_WALL_MAX = 0.15   # a side wall's end on the lip edge, of the edge's length


def _outer_mouth(part, whole):
    """The pan's mouth from its own outline, as pixel ends (a, b), or None:
    the longest straight side of `whole` that `part` (its tray, or its lip)
    runs along for at least half the side's length, facing within 45
    degrees of the way the part's place in the pan says (the side it sits
    nearest). The pan's outline holds the whole lip even where something
    lies across the tray, so the lip cannot lose to a side wall the way the
    tray's own sides could. An end is trimmed to the part's span when the
    part stops a wall's thickness short of it."""
    edge_c = max(whole, key=cv2.contourArea)
    part_c = max(part, key=cv2.contourArea)
    pts = np.concatenate([c.reshape(-1, 2) for c in list(part) + list(whole)])
    size = float(np.hypot(*(pts.max(0) - pts.min(0))))
    close = max(15.0, 0.08 * size)
    wx, wy, ww, wh = cv2.boundingRect(edge_c)
    px, py, pw, ph = cv2.boundingRect(part_c)
    gap = {"left": px - wx, "right": (wx + ww) - (px + pw),
           "up": py - wy, "down": (wy + wh) - (py + ph)}
    side = min(gap, key=gap.get)
    across = ("up", "down") if side in ("left", "right") else ("left", "right")
    also = [k for k in across if gap[k] <= max(10.0, 1.5 * gap[side])]
    if len(also) == 1:
        v, h = (side, also[0]) if side in ("up", "down") else (also[0], side)
        want = f"{v}-{h}"
    else:
        want = side
    m = cv2.moments(part_c)
    if m["m00"] <= 0:
        return None
    inside = np.array([m["m10"] / m["m00"], m["m01"] / m["m00"]])
    poly = cv2.approxPolyDP(edge_c, 0.012 * cv2.arcLength(edge_c, True), True).reshape(-1, 2)
    best, best_len = None, 0.0
    for k in range(len(poly)):
        p0 = poly[k].astype(np.float64)
        p1 = poly[(k + 1) % len(poly)].astype(np.float64)
        length = float(np.hypot(*(p1 - p0)))
        if length < 0.2 * size or length <= best_len:
            continue
        near = np.mean([abs(cv2.pointPolygonTest(part_c, (float(x), float(y)), True)) <= close
                        for x, y in (p0 + (p1 - p0) * f for f in np.linspace(0.05, 0.95, 11))])
        if near < 0.5:
            continue
        nx, ny = -(p1 - p0)[1] / length, (p1 - p0)[0] / length
        if ((p0 + p1) / 2.0 - inside) @ np.array([nx, ny]) < 0:
            nx, ny = -nx, -ny
        apart = abs(_COMPASS.index(compass(nx, ny)) - _COMPASS.index(want)) % 8
        if min(apart, 8 - apart) > 1:
            continue
        best, best_len = (p0, p1), length
    if best is None:
        return None
    # The side walls' ends lie on the same straight edge but are no
    # opening: an end the part stops short of by a wall's thickness is
    # trimmed. A longer stretch past the part is the part hidden under
    # something lying in the pan, and stays.
    p0, p1 = best
    u = (p1 - p0) / best_len
    t = (part_c.reshape(-1, 2).astype(np.float64) - p0) @ u
    lo, hi = max(0.0, float(t.min())), min(best_len, float(t.max()))
    wall = MOUTH_WALL_MAX * best_len
    lo = lo if lo <= wall else 0.0
    hi = hi if best_len - hi <= wall else best_len
    return p0 + u * lo, p0 + u * hi


def mouth_line(part, whole, grid):
    """The mouth as a straight segment ((col, row), (col, row)) in grid
    units, or None: from the pan's own outline (_outer_mouth) when it can;
    else the longest stretch of `part`'s outline lying on `whole`'s outer
    edge (for a dustpan's tray, that stretch is the mouth: everywhere else
    walls stand between the tray and the outside), or the part's longest
    straight side along the edge."""
    outer = _outer_mouth(part, whole)
    if outer is not None:
        a, b = outer
        return (grid.pixel_to_grid(float(a[0]), float(a[1])),
                grid.pixel_to_grid(float(b[0]), float(b[1])))
    pts = np.concatenate([c.reshape(-1, 2) for c in list(part) + list(whole)])
    x0, y0 = (pts.min(0) - 8).astype(int)
    x1, y1 = (pts.max(0) + 8).astype(int)
    shape = (y1 - y0 + 1, x1 - x0 + 1)
    band, line = np.zeros(shape, np.uint8), np.zeros(shape, np.uint8)
    cv2.drawContours(band, [(c - (x0, y0)).astype(np.int32) for c in whole], -1, 255, 9)
    cv2.drawContours(line, [(c - (x0, y0)).astype(np.int32) for c in part], -1, 255, 1)
    on = cv2.bitwise_and(band, line)
    n, labels, stats, _ = cv2.connectedComponentsWithStats(
        cv2.dilate(on, np.ones((5, 5), np.uint8)), connectivity=8)
    best = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA])) if n > 1 else 0
    ys, xs = np.nonzero((labels == best) & (on > 0)) if n > 1 else (np.zeros(0, int),) * 2
    found = None
    q = np.stack([xs + x0, ys + y0], 1).astype(np.float64)
    if len(xs) >= 12:
        mid = q.mean(0)
        _, spread, axes = np.linalg.svd(q - mid, full_matrices=False)
        if spread[1] <= 0.3 * spread[0]:        # a line, not a corner or a blob
            t = (q - mid) @ axes[0]
            found = (mid + axes[0] * t.min(), mid + axes[0] * t.max())
    # A thick lip keeps the tray a lip's width off the edge, so the band
    # above misses the mouth (and may find a thin side wall instead): the
    # tray's longest straight side running close along the outer edge is
    # the mouth then.
    edge_c = max(whole, key=cv2.contourArea)
    size = float(np.hypot(*(pts.max(0) - pts.min(0))))
    reach = max(12.0, 0.06 * size)

    def gap(x, y):
        return abs(cv2.pointPolygonTest(edge_c, (float(x), float(y)), True))

    def by_edge(x, y, within=None):
        return gap(x, y) <= (reach if within is None else within)

    def along_edge(x, y, within):
        """Still along the pan's edge: close to it, and not outside the pan
        (past a corner the line leaves the outline)."""
        d = cv2.pointPolygonTest(edge_c, (float(x), float(y)), True)
        return -3.0 <= d <= within

    tray_c = max(part, key=cv2.contourArea)
    poly = cv2.approxPolyDP(tray_c, 0.015 * cv2.arcLength(tray_c, True), True).reshape(-1, 2)
    straight = None
    for k in range(len(poly)):
        p0, p1 = poly[k].astype(np.float64), poly[(k + 1) % len(poly)].astype(np.float64)
        length = float(np.hypot(*(p1 - p0)))
        if length < 0.25 * size or (found is not None and length <= float(
                np.hypot(*(found[1] - found[0])))) or (straight is not None and length <= float(
                np.hypot(*(straight[1] - straight[0])))):
            continue
        if all(by_edge(*(p0 + (p1 - p0) * f)) for f in np.linspace(0.1, 0.9, 9)):
            straight = (p0, p1)
    if straight is not None:
        # Something lying on the pan (the brush) can hide part of the tray's
        # side along the lip: carry the line on while it still runs along the
        # pan's edge.
        p0, p1 = straight
        # only as far as the edge stays as close as along the part seen
        close = min(reach, 6.0 + max(gap(*(p0 + (p1 - p0) * f))
                                     for f in np.linspace(0.1, 0.9, 9)))
        step = (p1 - p0) / max(1e-6, float(np.hypot(*(p1 - p0)))) * 4.0
        while along_edge(*(p1 + step), close) and float(np.hypot(*(p1 - p0))) < size:
            p1 = p1 + step
        while along_edge(*(p0 - step), close) and float(np.hypot(*(p1 - p0))) < size:
            p0 = p0 - step
        found = (p0, p1)
    if found is None:
        return None
    a, b = found
    return (grid.pixel_to_grid(float(a[0]), float(a[1])),
            grid.pixel_to_grid(float(b[0]), float(b[1])))


def _mouth_note(mouth, inside):
    """("down-right", "from H9 to M6, about 5.2 cells wide") for a mouth
    segment, facing away from the point `inside` (the tray's centre)."""
    (ax, ay), (bx, by) = mouth
    width = math.hypot(bx - ax, by - ay)
    if width < 0.75:
        return None
    nx, ny = -(by - ay) / width, (bx - ax) / width
    mx, my = (ax + bx) / 2.0, (ay + by) / 2.0
    if (mx - inside[0]) * nx + (my - inside[1]) * ny < 0:
        nx, ny = -nx, -ny
    ends = []
    for x, y in ((ax, ay), (bx, by)):
        cell = (min(CONFIG.n_cols - 1, max(0, int(x))), min(CONFIG.n_rows - 1, max(0, int(y))))
        ends.append(coordinate_name(*cell))
    return (compass(nx, ny), f"from {ends[0]} to {ends[1]}, about {width:.1f} cells wide",
            {"a": (ax, ay), "b": (bx, by), "n": (nx, ny)})


def _box_of(poly):
    xs, ys = [q[0] for q in poly], [q[1] for q in poly]
    return min(xs), min(ys), max(xs), max(ys)


def _centre_of(e):
    return e.get("center_pt") or (lambda c: c and (c[0] + 0.5, c[1] + 0.5))(
        parse_coordinate(str(e.get("center") or "")))


_COMPASS = ("right", "up-right", "up", "up-left", "left", "down-left", "down",
            "down-right")


def note_opening(entry):
    """Which way an object's opening faces, in its DESC, when its parts show
    it: a lip lying along the object's outer edge (from the object's centre
    to the lip's), or a tray that reaches the edge on one side (that side).
    A lip lying along the edge for LIP_EDGE_SURE or more is taken as it is;
    a lip that only just qualifies and a tray disagreeing by more than 45
    degrees: nothing is written - a wrong direction is worse than none.
    (Measured on photos: a real rubber lip 0.89 along the edge, a brush's
    top named "lip" by mistake 0.32; a floor patch is no tray.)"""
    comps = entry.get("components") or []
    poly, centre = entry.get("polygon"), _centre_of(entry)
    if not comps or not poly or not centre:
        return
    lip_dir = lip = None
    lips = [c for c in comps if LIP_WORDS_RE.search(str(c.get("name") or ""))
            and c.get("edge", 0.0) >= LIP_EDGE_MIN]
    if lips:
        lip = max(lips, key=lambda c: len(_touch_cells(c)))
        at = _centre_of(lip)
        if at and (abs(at[0] - centre[0]) >= 0.25 or abs(at[1] - centre[1]) >= 0.25):
            lip_dir = compass(at[0] - centre[0], at[1] - centre[1])
    tray_dir = tray = None
    whole = max(_poly_area(poly), 1e-6)
    trays = [c for c in comps if TRAY_WORDS_RE.search(str(c.get("name") or ""))
             and c.get("polygon") and _poly_area(c["polygon"]) >= TRAY_MIN_SHARE * whole]
    if trays:
        tray = max(trays, key=lambda c: _poly_area(c["polygon"]))
        ox0, oy0, ox1, oy1 = _box_of(poly)
        tx0, ty0, tx1, ty1 = _box_of(tray["polygon"])
        gap = {"left": tx0 - ox0, "right": ox1 - tx1, "up": ty0 - oy0,
               "down": oy1 - ty1}
        side = min(gap, key=gap.get)
        rest = sorted(v for k, v in gap.items() if k != side)
        if gap[side] <= 0.6 * rest[0] or rest[0] - gap[side] >= 0.75:
            across = ("up", "down") if side in ("left", "right") else ("left", "right")
            also = [k for k in across if gap[k] <= max(0.5, 1.5 * gap[side])]
            if len(also) == 1:
                vertical, horizontal = ((side, also[0]) if side in ("up", "down")
                                        else (also[0], side))
                tray_dir = f"{vertical}-{horizontal}"
            else:
                tray_dir = side
    if lip_dir and tray_dir and lip.get("edge", 0.0) < LIP_EDGE_SURE:
        apart = abs(_COMPASS.index(lip_dir) - _COMPASS.index(tray_dir)) % 8
        if min(apart, 8 - apart) > 1:
            return
    # The mouth itself, where it can be measured: the lip's stretch of the
    # outer edge, else the tray's. Its own direction (square to it, away
    # from the inside) replaces the rough ones above.
    span = None
    if lip_dir and lip.get("mouth"):
        span = _mouth_note(lip["mouth"], centre)
        if span:
            apart = abs(_COMPASS.index(span[0]) - _COMPASS.index(lip_dir)) % 8
            if min(apart, 8 - apart) > 1:
                span = None
    elif tray is not None and tray.get("mouth") and not lip_dir:
        span = _mouth_note(tray["mouth"], _centre_of(tray) or centre)
        if span and tray_dir:
            apart = abs(_COMPASS.index(span[0]) - _COMPASS.index(tray_dir)) % 8
            if min(apart, 8 - apart) > 1:
                span = None
    if lip_dir:
        face = span[0] if span else lip_dir
        note = f"opening (its {lip['name']}) faces {face}"
    elif tray_dir or span:
        face = span[0] if span else tray_dir
        note = f"opening faces {face} (where its {tray['name']} reaches the edge)"
    else:
        return
    if span:
        note += f"; its mouth runs {span[1]}"
        entry["mouth_geo"] = span[2]
    elif tray is not None and not lip_dir and tray_dir:
        # No line measured (the tray stops short of a thick lip): its width
        # across the opening and its middle at the opening side still give
        # the planner the mouth's size and place.
        k = _COMPASS.index(tray_dir)
        dx, dy = math.cos(math.radians(45 * k)), -math.sin(math.radians(45 * k))
        pts = np.array(tray["polygon"], dtype=np.float64)
        across = pts @ np.array([-dy, dx])
        along = pts @ np.array([dx, dy])
        front = pts[along >= along.max() - 0.15 * (along.max() - along.min())]
        fx, fy = front.mean(0)
        cell = (min(CONFIG.n_cols - 1, max(0, int(fx))), min(CONFIG.n_rows - 1, max(0, int(fy))))
        note += (f"; its mouth is about {across.max() - across.min():.1f} cells wide, "
                 f"centred near {coordinate_name(*cell)}")
        mid = (across.max() + across.min()) / 2.0
        half = (across.max() - across.min()) / 2.0
        # the front line: through the front's middle, square to the opening
        base = np.array([fx, fy]) - np.array([-dy, dx]) * ((np.array([fx, fy]) @ np.array([-dy, dx])) - mid)
        entry["mouth_geo"] = {"a": tuple(base - np.array([-dy, dx]) * half),
                              "b": tuple(base + np.array([-dy, dx]) * half),
                              "n": (dx, dy)}
    entry["desc"] = f"{entry.get('desc', '')}; {note}".lstrip("; ")


def _flat_side_mouth(pts, c, size):
    """The mouth of a pan outlined without its handle, as guess_mouth's dict,
    or None: its one long straight side (a D-shaped pan's flat edge), facing
    away from the middle. A shape with no side clearly longer than the rest
    (a rectangle, a circle) gives none."""
    cnt = np.round(pts * 100).astype(np.int32).reshape(-1, 1, 2)
    poly2 = cv2.approxPolyDP(cnt, 0.012 * cv2.arcLength(cnt, True), True).reshape(-1, 2) / 100.0
    sides = []
    for i in range(len(poly2)):
        p0, p1 = poly2[i], poly2[(i + 1) % len(poly2)]
        sides.append((float(np.hypot(*(p1 - p0))), p0, p1))
    sides.sort(key=lambda t: -t[0])
    if not sides or sides[0][0] < 0.45 * size:
        return None
    if len(sides) > 1 and sides[0][0] < 1.6 * sides[1][0]:
        return None
    length, p0, p1 = sides[0]
    n = np.array([-(p1 - p0)[1], (p1 - p0)[0]]) / length
    if ((p0 + p1) / 2.0 - c) @ n < 0:
        n = -n
    return {"a": tuple(p0), "b": tuple(p1), "n": (float(n[0]), float(n[1]))}


def guess_mouth(poly):
    """{"a", "b", "n"} (grid units) for a dustpan outlined whole, or None:
    its handle is the far protrusion, and its mouth the longest straight
    side facing away from the handle (within about 45 degrees). Without a
    handle in the outline: its one long flat side."""
    try:
        pts = np.array([(float(x), float(y)) for x, y in poly], np.float64)
    except (TypeError, ValueError):
        return None
    if len(pts) < 3:
        return None
    size = float(np.hypot(*np.ptp(pts, axis=0)))
    c = np.array(_poly_centroid([tuple(q) for q in pts]), np.float64)
    dense = []
    for i, a in enumerate(pts):
        b = pts[(i + 1) % len(pts)]
        k = max(1, int(math.ceil(float(np.hypot(*(b - a))) / 0.1)))
        dense.extend(a + (b - a) * j / k for j in range(k))
    dense = np.array(dense)
    dist = np.hypot(*(dense - c).T)
    tip = dense[int(dist.argmax())]
    if float(dist.max()) < 1.3 * float(np.median(dist)):
        return _flat_side_mouth(pts, c, size)   # no handle: its one long flat side
    away = -(tip - c) / max(1e-9, float(np.hypot(*(tip - c))))
    cnt = np.round(pts * 100).astype(np.int32).reshape(-1, 1, 2)
    poly2 = cv2.approxPolyDP(cnt, 0.012 * cv2.arcLength(cnt, True), True).reshape(-1, 2) / 100.0
    best, best_len = None, 0.0
    for i in range(len(poly2)):
        p0, p1 = poly2[i], poly2[(i + 1) % len(poly2)]
        length = float(np.hypot(*(p1 - p0)))
        if length < 0.25 * size or length <= best_len:
            continue
        n = np.array([-(p1 - p0)[1], (p1 - p0)[0]]) / length
        if ((p0 + p1) / 2.0 - c) @ n < 0:
            n = -n
        if n @ away >= 0.7:
            best, best_len = (p0, p1, n), length
    if best is None:
        return None
    p0, p1, n = best
    return {"a": tuple(p0), "b": tuple(p1), "n": (float(n[0]), float(n[1]))}


SWEEP_TASK_RE = re.compile(r"(?<!\w)(sweep\w*|broom\w*|dust ?pan|dustpan)(?!\w)", re.I)
SWEEP_MIN_STROKES = 4   # distinct mouth lanes, whenever the measured opening allows
SWEEP_DEPTH = 5         # the cleaning area runs this many cells out from the mouth
SWEEP_STOP_IN = 0.15    # the claw comes to rest this far into a cell, past the edge it came in by
SWEEP_LIP_IN = 0.5      # a stroke ends with the bristles' front this far past the lip
SWEEP_FULL = (0.45, 1.0)  # how far behind the front bristles still carry dust in: tried both
SWEEP_BACK = 0.3        # a stroke through the pan stops this far short of where it narrows
SWEEP_WALL = 0.05       # margin off the mouth's ends (it is measured to the tray's span)
_COLLECTOR_RE = re.compile(r"(?<!\w)(dust ?pan|dustpan|scoop|collector)(?!\w)")
_BRUSH_RE = re.compile(r"(?<!\w)(broom|brush|sweeper|whisk)(?!\w)")
_BRISTLE_RE = re.compile(r"(?<!\w)(bristles?|brush head|broom head|head)(?!\w)")
_DEBRIS_RE = re.compile(
    r"(?<!\w)(dust|dirt|debris|crumbs?|scraps?|litter|trash|rubbish|leaves|leaf|"
    r"sand|rice|seeds?|grains?|chips|flakes|lint|fluff|mess|spill|particles|"
    r"bits|pieces|wrappers?)(?!\w)")


def is_sweep_task(task) -> bool:
    return bool(SWEEP_TASK_RE.search(task or ""))


def _names_of(o):
    aka = o.get("aka") or []
    aka = [aka] if isinstance(aka, str) else list(aka)
    return " ".join([str(o.get("name") or "")] + [str(a) for a in aka]).lower()


def _goto_line(cell):
    name = coordinate_name(*cell)
    letters = "".join(ch for ch in name if ch.isalpha())
    return f"goto_coordinate = {letters}, {name[len(letters):]}"


def gantry_stop(pos, cell):
    """Where the claw comes to rest for a goto to `cell` from `pos` (cells;
    `pos` continuous). The gantry runs one axis at a time, vertical first
    (build_path_commands), and the guidance stops it the moment the tag is
    seen inside the target cell: just past the edge it came in by. An axis
    that did not have to move keeps its place."""
    x, y = float(pos[0]), float(pos[1])
    c, r = cell
    if r != math.floor(y):
        y = r + SWEEP_STOP_IN if r > y else r + 1 - SWEEP_STOP_IN
    if c != math.floor(x):
        x = c + SWEEP_STOP_IN if c > x else c + 1 - SWEEP_STOP_IN
    return np.array([x, y])


def _fill_points(polys, step):
    """Points (cells, continuous) filling the given outlines, edges included."""
    if not polys:
        return np.zeros((0, 2))
    k = int(round(1.0 / step))
    allp = np.vstack(polys)
    lo = np.floor(allp.min(0)) - 1
    size = ((np.ceil(allp.max(0)) + 1 - lo) * k).astype(int) + 1
    mask = np.zeros((size[1], size[0]), np.uint8)
    for poly in polys:
        cv2.fillPoly(mask, [np.round((poly - lo) * k).astype(np.int32)], 1)
    ys, xs = np.nonzero(mask)
    return np.stack([xs, ys], 1) / float(k) + lo


def _cell_square(c):
    return np.array([(c[0], c[1]), (c[0] + 1, c[1]), (c[0] + 1, c[1] + 1), (c[0], c[1] + 1)],
                    np.float64)


def sweep_recipe(objects):
    """The sweep, computed: {"lines", "lanes", "covered", "target", "brush",
    "collector", "dirt_lanes", "note", ...} -- or {"note": why not} / None
    when the board has no dustpan with a measured mouth and no brush.

    Built for how the gantry really moves (one axis at a time, stopping just
    inside a cell's edge -- gantry_stop):
      - the brush is picked up at the middle of its outline, coming in
        diagonally from a neighbour, so the claw's resting point -- and so
        the bristles' place relative to it -- is known;
      - every stroke is ONE straight move along the axis that points most
        nearly into the mouth, from behind the dust until the bristles'
        front is SWEEP_LIP_IN past the lip, never onto the pan's walls;
        lanes sit side by side across the mouth, overlapping;
      - dust off to the side of the mouth (outside what those strokes can
        carry in, outlined dirt included) is first pushed sideways into
        their path (feed strokes) -- a sideways slide never carries a pile,
        so nothing slides along the lip;
      - each stroke start is lined up from the side that puts the claw
        where the lane needs it.
    Commands are the CLAW's cells (the pickup is at the grip cell already,
    so Gripper AI has nothing to shift)."""
    pans = [o for o in objects or () if _COLLECTOR_RE.search(_names_of(o))
            and (o.get("mouth_geo") or o.get("polygon"))]
    pans.sort(key=lambda o: not o.get("mouth_geo"))
    brushes = [o for o in objects or () if _BRUSH_RE.search(_names_of(o))
               and not _COLLECTOR_RE.search(_names_of(o))]
    if not pans or not brushes:
        return None
    pan, brush = pans[0], brushes[0]
    pick_notes = []
    geo = pan.get("mouth_geo")
    if not geo:
        geo = _mouth_trimmed(pan.get("polygon"))
        if not geo:
            return {"note": f"the {pan['name']}'s mouth could not be told from its outline"}
        pick_notes.append(f"the {pan['name']}'s mouth is taken from its shape "
                          "(the side facing away from its handle, or its long flat side)")
    home = parse_coordinate(str(brush.get("center") or ""))
    if home is None:
        return {"note": "the brush has no cell to pick it up at"}
    cells, polys = [], []
    for comp in brush.get("components") or []:
        if _BRISTLE_RE.search(str(comp.get("name") or "").lower()):
            cells += [parse_coordinate(x) for x in _touch_cells(comp)]
            if comp.get("polygon") and len(comp["polygon"]) >= 3:
                polys.append(np.array(comp["polygon"], np.float64))
    cells = [c for c in cells if c is not None] or [
        c for c in (parse_coordinate(x) for x in _touch_cells(brush)) if c is not None]
    if not cells:
        return {"note": "the brush's bristles have no cells"}
    reach = reachable_cells()
    if reach is None:
        return {"note": "no cell is reachable"}

    def reachable(c):
        return reach[0] <= c[0] < reach[2] and reach[1] <= c[1] < reach[3]

    if not reachable(home):
        return {"note": f"the brush at {coordinate_name(*home)} is out of reach"}
    A, B = np.array(geo["a"], np.float64), np.array(geo["b"], np.float64)
    N = np.array(geo["n"], np.float64)
    N /= max(1e-9, float(np.hypot(*N)))
    W = float(np.hypot(*(B - A)))
    if W < 0.75:
        return {"note": "the dustpan's mouth is too short to sweep into"}
    T = (B - A) / W
    L = (A + B) / 2.0
    bristles = _fill_points(polys or [_cell_square(c) for c in cells], 0.1)
    bw = float(np.ptp(bristles @ T))
    if bw > W + 1.5:
        return {"note": f"the bristles ({bw:.1f} cells across) are wider than the "
                        f"dustpan's mouth ({W:.1f} cells)"}
    # -- the pickup: diagonally into the grip cell, so the claw rests just
    # inside the corner it came in by -- the one deepest on the brush
    grip = parse_coordinate(middle_grip_cell(brush)) or home
    if not reachable(grip):
        grip = home
    outline = brush.get("polygon")
    shape = (np.array(outline, np.float32).reshape(-1, 1, 2)
             if outline and len(outline) >= 3 else None)
    own = np.array([(c + 0.5, r + 0.5) for c, r in
                    (parse_coordinate(x) for x in _touch_cells(brush)) if c is not None]
                   or [(home[0] + 0.5, home[1] + 0.5)])
    corners = []
    for sx in (1, -1):
        for sy in (-1, 1):
            wp = (grip[0] + sx, grip[1] + sy)
            if not reachable(wp):
                continue
            q = gantry_stop((wp[0] + 0.5, wp[1] + 0.5), grip)
            depth = (cv2.pointPolygonTest(shape, (float(q[0]), float(q[1])), True)
                     if shape is not None else -float(np.hypot(*(own - q).T).min()))
            corners.append((depth, wp, q))
    corners.sort(key=lambda c: -c[0])
    # every corner the claw would rest on the brush at is a candidate: which
    # one sets where on the cell grid the bristles can be put
    firm = ([c for c in corners if c[0] >= min(0.1, corners[0][0]) - 1e-9]
            if corners else [])

    # -- where the bristles may go
    half = W / 2.0 - SWEEP_WALL
    k_px = 10
    pan_poly = pan.get("polygon")
    if pan_poly and len(pan_poly) >= 3:
        mask = np.zeros((CONFIG.n_rows * k_px, CONFIG.n_cols * k_px), np.uint8)
        cv2.fillPoly(mask, [np.round(np.array(pan_poly, np.float64) * k_px).astype(np.int32)], 1)
        mask = cv2.dilate(mask, np.ones((3, 3), np.uint8))

        def in_pan(X):
            ix = np.clip((X[:, 0] * k_px).astype(int), 0, mask.shape[1] - 1)
            iy = np.clip((X[:, 1] * k_px).astype(int), 0, mask.shape[0] - 1)
            return mask[iy, ix] > 0
    else:
        def in_pan(X):
            q = X - L
            return (q @ N < 0.1) & (np.abs(q @ T) < W / 2.0 + 0.6)

    # -- what to sweep: the area in front of the mouth, and outlined dirt
    grid_a = np.arange(0.5, SWEEP_DEPTH + 1e-9, 0.25)
    grid_b = np.arange(-half, half + 1e-9, 0.25)
    pts0 = np.array([L + a * N + b * T for a in grid_a for b in grid_b])
    target = set()
    for c in range(CONFIG.n_cols):
        for r in range(CONFIG.n_rows):
            q = np.array([c + 0.5, r + 0.5]) - L
            # the floor in front of the lip; cells on the lip line itself
            # are the dustpan's edge
            if 0.5 <= q @ N <= SWEEP_DEPTH and abs(q @ T) <= W / 2.0:
                target.add((c, r))
    for d in objects or ():
        if d is pan or d is brush or not _DEBRIS_RE.search(_names_of(d)):
            continue
        dc = [c for c in (parse_coordinate(x) for x in _touch_cells(d)) if c is not None]
        if not dc:
            continue
        dp = _fill_points([np.array(d["polygon"], np.float64)]
                          if d.get("polygon") and len(d["polygon"]) >= 3
                          else [_cell_square(c) for c in dc], 0.25)
        q = dp - L
        dp = dp[~((q @ N < 0) & (np.abs(q @ T) < W / 2.0))]      # already in the pan
        if len(dp):
            target |= set(dc)
            pts0 = np.vstack([pts0, dp])
    tcells = sorted(target)
    tpts0 = np.array([(c + 0.5, r + 0.5) for c, r in tcells]) if tcells else np.zeros((0, 2))

    def place(pos, want, precise, fits=None):
        """Gotos to a cell near `want` (a claw point) whose resting point
        is nearest `want` along `precise` (x or y) and `fits`: straight
        there, or lined up from the neighbour on either side along that
        axis. -> (gotos, resting point), or None."""
        best_p = None
        base = (int(math.floor(want[0])), int(math.floor(want[1])))
        other = np.abs(np.array([precise[1], precise[0]]))
        for dx in (-2, -1, 0, 1, 2):
            for dy in (-2, -1, 0, 1, 2):
                cell = (base[0] + dx, base[1] + dy)
                if not reachable(cell):
                    continue
                for way in ([cell],):
                    if not all(reachable(c) for c in way):
                        continue
                    q = np.array(pos, np.float64)
                    for c in way:
                        q = gantry_stop(q, c)
                    if fits is not None and not fits(q):
                        continue
                    score = (10 * abs((q - want) @ precise) + abs((q - want) @ other)
                             + 0.01 * (len(way) - 1))
                    if best_p is None or score < best_p[0]:
                        best_p = (score, way, q)
        return None if best_p is None else (best_p[1], best_p[2])

    axes = {"up": (0.0, -1.0), "down": (0.0, 1.0), "left": (-1.0, 0.0), "right": (1.0, 0.0)}

    def sweep_with(approach, p_pick, full_lag):
        """The best sweep with the claw resting at p_pick on the brush."""
        S = bristles - p_pick                    # the bristles, from the claw
        # how far in the pan stays about as wide as its mouth (a handle or a
        # tapering back is no place for the bristles)
        pan_depth = 2.0
        if pan.get("polygon"):
            fill = np.zeros((CONFIG.n_rows * 10, CONFIG.n_cols * 10), np.uint8)
            cv2.fillPoly(fill, [np.round(np.array(pan["polygon"], np.float64) * 10).astype(np.int32)], 1)
            inner = cv2.erode(fill, np.ones((7, 7), np.uint8))     # the walls' thickness off
            ts = np.linspace(-half, half, 41)
            pan_depth = 0.0
            for d in np.arange(0.5, 16.01, 0.25):
                row = L - d * N + np.outer(ts, T)
                ix = np.clip((row[:, 0] * 10).astype(int), 0, inner.shape[1] - 1)
                iy = np.clip((row[:, 1] * 10).astype(int), 0, inner.shape[0] - 1)
                if (inner[iy, ix] > 0).mean() < 0.9:
                    break
                pan_depth = float(d)

        def legal(P):
            """No bristle on the pan's walls: on the pan's outline only through
            the opening (in front of the lip, or just past it)."""
            X = S + P
            q = X - L
            wall = (np.abs(q @ T) > half + 0.05) | (q @ N < -(max(pan_depth, 2.0) + 0.3))
            return not (in_pan(X) & wall).any()

        def slices(perp, u):
            """The bristles cut across `perp` in 0.1-cell slices (the first one
            starting half a slice before them, so no point sits on a slice's
            edge): each slice's front and back along the move direction `u`."""
            v = S @ perp
            v0 = float(v.min()) - 0.05
            idx = np.floor((v - v0) / 0.1).astype(int)
            a = S @ u
            front = np.full(idx.max() + 1, np.nan)
            back = np.full_like(front, np.nan)
            for k in range(len(front)):
                m = idx == k
                if m.any():
                    front[k], back[k] = a[m].max(), a[m].min()
            return v0, front, back

        def behind(points, q, u, perp):
            """How far along u a claw (across at q) may sit with every point
            that its bristles cover still ahead of their back -- slice by slice,
            so a tilted head's slanted back edge does not leave dust behind."""
            v0, _, back = slices(perp, u)
            # the most forward back within 0.2 cells either side: the claw's
            # resting point is only known to about that much
            pad = np.concatenate([np.full(2, np.nan), back, np.full(2, np.nan)])
            with np.errstate(all="ignore"):
                back = np.nanmax(np.stack([pad[i:i + len(back)] for i in range(5)]), 0)
            k = np.floor((points @ perp - q @ perp - v0) / 0.1).astype(int)
            ok = (k >= 0) & (k < len(back))
            b = np.where(ok, back[np.clip(k, 0, len(back) - 1)], np.nan)
            ok &= ~np.isnan(b)
            return float((points[ok] @ u - b[ok]).min()) - 0.05 if ok.any() else math.inf

        def full_part(perp, u):
            """The bristles' extent across `perp` counting only the slices whose
            front (along u) is within `full_lag` of the foremost: a tilted
            head's thin wedge drags dust only part of the way."""
            v0, front, _ = slices(perp, u)
            full = np.nonzero(~np.isnan(front) & (front >= np.nanmax(front) - full_lag))[0]
            v = S @ perp
            own = np.isin(np.floor((v - v0) / 0.1).astype(int), full)
            return float(v[own].min()), float(v[own].max())

        def carry(points, P0, P1, u, perp):
            """Dust in the bristles' way from P0 to P1 (a straight move along u)
            ends just past their front. -> (points, moved mask)."""
            v0, front, back = slices(perp, u)
            k = np.floor((points @ perp - P0 @ perp - v0) / 0.1).astype(int)
            ok = (k >= 0) & (k < len(front))
            f = np.where(ok, front[np.clip(k, 0, len(front) - 1)], np.nan)
            b = np.where(ok, back[np.clip(k, 0, len(front) - 1)], np.nan)
            a = points @ u
            hit = ~np.isnan(f) & (a >= P0 @ u + b - 1e-9) & (a <= P1 @ u + f)
            out = points.copy()
            out[hit] += ((P1 @ u + f[hit] + 0.05) - a[hit])[:, None] * u
            return out, hit

        def plan(push):
            """The sweep with every stroke into the mouth moving `push`."""
            d1 = np.array(axes[push])
            e = np.abs(d1[::-1])                 # across the strokes: x or y
            ends = [(L - T * half) @ e, (L + T * half) @ e]
            b_lo, b_hi = min(ends), max(ends)    # what a stroke can carry in
            v0_m, front_m, _ = slices(e, d1)
            lat_m = v0_m + (np.arange(len(front_m)) + 0.5) * 0.1
            live = ~np.isnan(front_m) & (front_m >= np.nanmax(front_m) - full_lag)

            def lip_past(P):
                """How far each bristle slice that meets the lip inside the
                opening has its front past the lip, along the stroke."""
                X = P + np.outer(lat_m[live], e) + np.outer(front_m[live], d1)
                past = ((X - L) @ N) / float(d1 @ N)
                cross = X - np.outer(past, d1)
                return past[np.abs((cross - L) @ T) <= half + 0.05]

            def delivered(P):
                """The front SWEEP_LIP_IN past the lip, and every slice that
                carries dust at least 0.2 past it."""
                past = lip_past(P)
                return len(past) > 0 and past.max() >= SWEEP_LIP_IN and bool((past >= 0.2).all())

            def through(P):
                """Past the lip and on through the pan, to SWEEP_BACK short of its far side."""
                past = lip_past(P)
                return (len(past) > 0 and past.max() >= max(SWEEP_LIP_IN, pan_depth - SWEEP_BACK)
                        and bool((past >= 0.2).all()))

            notes, lines, lanes, stops = [], [], [], []
            if approach is not None:
                lines.append(f"{_goto_line(approach)}   # line up with the {brush['name']}'s grip")
            lines += [f"{_goto_line(grip)}   # pick up the {brush['name']}", "pickup"]
            st = {"pts": pts0.copy(), "tpts": tpts0.copy(), "pos": p_pick.copy(), "feeds": 0,
                  "main": 0}

            def trace(cell0, P0, u, done):
                """A pressed move from P0 along u until `done(P)`, never onto
                the pan. -> (resting point, cell) at its end, or (None, None)."""
                step = (int(round(u[0])), int(round(u[1])))
                P_end, end_cell, n = None, None, 1
                while True:
                    c = (cell0[0] + step[0] * n, cell0[1] + step[1] * n)
                    if not reachable(c):
                        break
                    prev = P0 if P_end is None else P_end
                    P = gantry_stop(prev, c)
                    if not all(legal(prev + (P - prev) * f) for f in np.linspace(0.25, 1.0, 4)):
                        break
                    P_end, end_cell = P, c
                    if done(P):
                        break
                    n += 1
                return P_end, end_cell

            def run_stroke(way, P0, u, perp, done, label, end_note, ends=None):
                """Press at P0, move along u until `done(P)` (or to `ends`, an
                already traced end), release. -> the resting point at the end,
                or None."""
                cell0 = way[-1]
                P_end, end_cell = ends or trace(cell0, P0, u, done)
                if end_cell is None:
                    return None
                for k, c in enumerate(way):
                    lines.append(_goto_line(c) + ("   # " + label if k == len(way) - 1 else
                                                  "   # line up"))
                lines.extend(["press", f"{_goto_line(end_cell)}   # {end_note}", "release"])
                lanes.append([cell0, end_cell])
                stops.append((P0, P_end))
                st["pts"], _ = carry(st["pts"], P0, P_end, u, perp)
                st["tpts"], _ = carry(st["tpts"], P0, P_end, u, perp)
                st["pos"] = P_end
                return P_end

            # -- feed strokes: dust beyond the mouth's span, pushed sideways
            # into it, one bristle-width row at a time
            for side in (-1, 1):
                u = -side * e
                g_lo, g_hi = full_part(d1, u)
                goal = (b_lo + min(1.0, 0.5 * (b_hi - b_lo)) if side < 0
                        else b_hi - min(1.0, 0.5 * (b_hi - b_lo)))
                given_up = np.zeros(len(st["pts"]), bool)
                for _ in range(16):
                    pts = st["pts"]
                    beyond = ((pts @ e < b_lo - 0.4) if side < 0 else (pts @ e > b_hi + 0.4)) & ~given_up
                    if not beyond.any():
                        break
                    a_lo = float((pts[beyond] @ d1).min())
                    row = beyond & (pts @ d1 <= a_lo + (g_hi - g_lo) - 0.05)
                    back = float((pts[row] @ u).min())
                    cover = (lambda q, a_lo=a_lo: q @ d1 + g_lo <= a_lo + 0.05
                             and q @ d1 + g_hi >= a_lo + 0.3)
                    done = ((lambda P: P @ e + float((S @ e).max()) >= goal) if side < 0
                            else (lambda P: P @ e + float((S @ e).min()) <= goal))
                    # the row nearest the outermost dust first; one a little
                    # further over when that one would catch the pan's corner
                    best_f, seen = None, set()
                    for shift in (0.0, 0.35, 0.7, 1.0, -0.35, -0.7):
                        want = ((back - 0.3 - float((S @ u).min())) * u
                                + (a_lo - g_lo + shift) * d1)
                        rp = pts[row]
                        got = (place(st["pos"], want, d1, lambda q: cover(q) and
                                     q @ u <= behind(rp, q, u, d1))
                               or place(st["pos"], want, d1, cover))
                        if got is None or tuple(np.round(got[1], 3)) in seen:
                            continue
                        seen.add(tuple(np.round(got[1], 3)))
                        P_end, end_cell = trace(got[0][-1], got[1], u, done)
                        if end_cell is None:
                            continue
                        moved, _ = carry(pts, got[1], P_end, u, d1)
                        gain = int((row & ~((moved @ e < b_lo - 0.4) | (moved @ e > b_hi + 0.4))).sum())
                        if best_f is None or gain > best_f[0]:
                            best_f = (gain, got, (P_end, end_cell))
                    if best_f is None or best_f[0] == 0:
                        notes.append(f"dust beside the mouth cannot be reached without "
                                     f"touching the {pan['name']}")
                        given_up |= row
                        continue
                    way, P0 = best_f[1]
                    if P0 @ u > behind(pts[row], P0, u, d1) + 0.05:
                        notes.append("a feed stroke starts short (reach)")
                    end = run_stroke(
                        way, P0, u, d1, done,
                        f"feed {st['feeds'] + 1}: from beyond the dust beside the mouth",
                        f"pushes it in front of the {pan['name']}'s mouth", ends=best_f[2])
                    if end is None:
                        notes.append(f"dust beside the mouth cannot be reached without "
                                     f"touching the {pan['name']}")
                        given_up |= row
                        continue
                    st["feeds"] += 1
                    pts = st["pts"]
                    still = ((pts @ e < b_lo - 0.4) if side < 0 else (pts @ e > b_hi + 0.4)) & row
                    if still.any():
                        notes.append(f"a feed stroke stops at the {pan['name']}'s side")
                        given_up |= still

            # -- the strokes into the mouth, side by side across it, each
            # overlapping the last
            f_lo, f_hi = full_part(e, d1)
            g_lo = float((S @ d1).min())
            inside = (lambda q: q @ e + f_lo >= b_lo - 0.05 and q @ e + f_hi <= b_hi + 0.05)
            lo_l, hi_l = b_lo - f_lo, b_hi - f_hi
            if hi_l <= lo_l:
                lats = [0.5 * (lo_l + hi_l)]
            else:
                lats = [lo_l + t for t in range(int(math.floor(hi_l - lo_l + 1e-6)) + 1)]
                if hi_l - lats[-1] > 0.25:
                    lats.append(hi_l)
                if hi_l - lo_l >= SWEEP_MIN_STROKES - 1:
                    # Keep at least four distinct one-cell-spaced lanes when
                    # the opening and bristle footprint leave room for them.
                    lats.extend(lo_l + i for i in range(SWEEP_MIN_STROKES))
                    lats = sorted(set(round(lat, 6) for lat in lats))
            if abs(lats[-1] - st["pos"] @ e) < abs(lats[0] - st["pos"] @ e):
                lats.reverse()
            used = set()
            for lat in lats:
                k = st["main"] + 1              # strokes are numbered as they are written
                fits = (lambda q, u=used: inside(q) and int(math.floor(q @ e)) not in u)
                pts = st["pts"]
                ahead = ((pts - L) @ N > 0.0) & (pts @ e >= lat + f_lo - 0.4) & (pts @ e <= lat + f_hi + 0.4)
                got = None
                if ahead.any():
                    ap = pts[ahead]
                    a_min = float((ap @ d1).min())
                    for pull in np.arange(0.0, 8.01, 0.5):
                        # behind the farthest dust, pulled in only for the reach
                        got = place(st["pos"], lat * e + (a_min - 0.3 - g_lo + pull) * d1, e,
                                    (lambda q, f=fits, p=pull: (f is None or f(q))
                                     and q @ d1 <= behind(ap, q, d1, e) + p))
                        if got is not None:
                            break
                    if got is None:
                        notes.append(f"stroke {k} is out of reach")
                        continue
                    way, P0 = got
                    first_row = int(math.floor(P0 @ e))
                    used.add(first_row)
                    # a stroke the walls stop at the lip (a tilted head's
                    # corner poking past the mouth's end) goes in further
                    # toward the middle instead, when that gets it in
                    traced = trace(way[-1], P0, d1, through)
                    mid = 0.5 * (b_lo + b_hi)
                    for nudge in (0.2, 0.6):
                        if traced[1] is not None and delivered(traced[0]):
                            break
                        side_in = 1.0 if P0 @ e < mid else -1.0
                        alt = place(st["pos"], P0 + side_in * nudge * e, e,
                                    lambda q, p=P0, n=nudge: inside(q)
                                    and int(math.floor(q @ e)) not in used - {first_row}
                                    and (q @ e - p @ e) * side_in >= n - 0.05
                                    and q @ d1 <= behind(ap, q, d1, e) + 0.5)
                        if alt is None:
                            continue
                        t2 = trace(alt[0][-1], alt[1], d1, through)
                        if t2[1] is not None and delivered(t2[0]):
                            way, P0, traced = alt[0], alt[1], t2
                            used.discard(first_row)
                            first_row = int(math.floor(P0 @ e))
                            used.add(first_row)
                    short = P0 @ d1 - behind(ap, P0, d1, e)
                    if short > 0.05:
                        notes.append(f"stroke {k} starts {short:.1f} cells short (reach)")
                    end = run_stroke(way, P0, d1, e, through,
                                     f"stroke {k}: behind the dust",
                                     f"{push} through the {pan['name']}", ends=traced)
                    if end is None:
                        notes.append(f"stroke {k} cannot move without touching the {pan['name']}")
                    else:
                        st["main"] += 1
                        past = lip_past(end)
                        if not len(past) or past.min() < 0.05:
                            notes.append(f"stroke {k} stops short of the lip (the walls)")
            if st["main"] < SWEEP_MIN_STROKES:
                notes.append(f"only {st['main']} distinct lanes fit the measured mouth "
                             "and bristle footprint")
            if approach is not None:
                lines.append(f"{_goto_line(approach)}   # back to the {brush['name']}'s place")
            lines += [f"{_goto_line(grip)}   # the {brush['name']} back where it was", "keep"]
            q = st["tpts"] - L
            got_in = (q @ N < 0) & (np.abs(q @ T) <= W / 2.0)
            covered = {c for c, ok in zip(tcells, got_in) if ok}
            qd = st["pts"] - L
            score = float(((qd @ N < 0) & (np.abs(qd @ T) <= W / 2.0)).mean()) if len(qd) else 0.0
            return {"lines": lines, "lanes": lanes, "covered": len(covered), "target": len(target),
                    "covered_cells": covered, "brush": brush["name"], "dirt_lanes": st["feeds"],
                    "score": score,
                    "strokes": st["main"], "axis": push, "pick": tuple(p_pick), "stops": stops,
                    "bristles_from_claw": tuple(S.mean(0)), "collector": pan["name"],
                    "note": "; ".join(dict.fromkeys(pick_notes + notes))}

        # the axes that point into the mouth: plan with each, keep the best
        into = sorted((k for k in axes if -(np.array(axes[k]) @ N) >= 0.45),
                      key=lambda k: -(np.array(axes[k]) @ N))
        best_plan = None
        for push in into:
            p_ = plan(push)
            if not p_["lanes"]:
                continue
            if best_plan is None or (round(p_["score"], 3), -len(p_["lanes"])) > (
                    round(best_plan["score"], 3), -len(best_plan["lanes"])):
                best_plan = p_
        return best_plan

    # the gantry sits at the bottom middle of the board, goes up to the grip's
    # row and then along it: it rests just inside the cell's lower edge and
    # just inside its side facing the middle
    direct = np.array([
        grip[0] + (SWEEP_STOP_IN if grip[0] + 0.5 > CONFIG.n_cols / 2.0 else 1.0 - SWEEP_STOP_IN),
        grip[1] + 1.0 - SWEEP_STOP_IN])
    # (with no outline, the grip cell itself is on the brush)
    direct_depth = (cv2.pointPolygonTest(shape, (float(direct[0]), float(direct[1])), True)
                    if shape is not None else 0.5)
    if direct_depth >= 0.1 or not firm:
        firm = [(direct_depth, None, direct)]       # straight to the grip cell
    else:
        pick_notes.append("the pickup lines up from a neighbouring cell "
                          "(the grip is a thin part)")
    best = None
    for depth, approach, p_pick in firm:
        for full_lag in SWEEP_FULL:
            got = sweep_with(approach, np.array(p_pick, np.float64), full_lag)
            if got is not None and (best is None or (round(got["score"], 3), -len(got["lanes"]), depth) > (
                    round(best[0]["score"], 3), -len(best[0]["lanes"]), best[1])):
                best = (got, depth)
    if best is None:
        return {"note": "; ".join(pick_notes) or "no stroke fits"}
    return best[0]


def sweep_recipe_text(rec) -> str:
    """The SWEEP RECIPE block for the planner's input."""
    head = (f"SWEEP RECIPE (computed by HOS X from the {rec['collector']}'s measured "
            f"mouth and the {rec['brush']}'s bristles: {len(rec['lanes'])} straight "
            f"stroke(s), each one move {rec.get('axis', 'in')} into the mouth"
            + (f" except {rec['dirt_lanes']} first pushing dust from beside the mouth "
               "in front of it" if rec.get("dirt_lanes") else "")
            + f"; {rec.get('strokes', 0)} distinct main lane(s), target at least "
            f"{SWEEP_MIN_STROKES} whenever the measured geometry allows"
            + f", covering {rec['covered']} of the {rec['target']} cells of the "
            f"{SWEEP_DEPTH}-step area outside the mouth and the dirt"
            + (f"; {rec['note']}" if rec.get("note") else "")
            + ") - write these lines exactly, in this order, then anything "
              "else the task asks:")
    return head + "\n" + "\n".join(rec["lines"])


def _pressed_runs(text):
    """The cells of every press ... release run in a plan, in order."""
    runs, run = [], None
    for line in (text or "").splitlines():
        bare = re.sub(r"^\s*\d+[.)]\s*", "", line.split("#")[0]).strip().lower()
        m = re.match(r"goto_coordinate\s*=\s*([a-z]+)\s*,\s*(\d+)", bare)
        if bare == "press":
            run = []
        elif bare == "release":
            if run is not None:
                runs.append(run)
            run = None
        elif m and run is not None:
            run.append(f"{m.group(1).upper()}{m.group(2)}")
    return runs


def sweep_followed(plan, rec) -> bool:
    """True when the plan's pressed strokes are exactly the recipe's."""
    want = _pressed_runs("\n".join(rec["lines"]))
    return _pressed_runs(plan) == want


def sweep_plan_text(rec, why="the planner's strokes did not match it") -> str:
    """A whole plan made of the recipe: for when the planner's differs, and
    for a plain sweep, where the planner is not asked at all."""
    strokes = rec.get("strokes")
    limit_note = (f"# Only {strokes} distinct broom lanes fit the measured "
                  "mouth and bristle footprint.\n"
                  if strokes is not None and strokes < SWEEP_MIN_STROKES else "")
    return ("PLAN:\n- sweep into the " + rec["collector"] + ": " + rec["brush"] + ", "
            + rec["collector"] + " | after: holding nothing\n"
            "# Sweep computed by HOS X from the measured mouth (" + why + ").\n"
            + limit_note
            + "\n".join(rec["lines"]) + "\nTask_Completed")


def merge_outlines(outlines):
    """One outline (a list of contours) covering several touching outlines:
    their union, the hairline seams between them closed."""
    pts = np.concatenate([c.reshape(-1, 2) for o in outlines for c in o])
    x0, y0 = (pts.min(0) - 4).astype(int)
    x1, y1 = (pts.max(0) + 4).astype(int)
    mask = np.zeros((y1 - y0 + 1, x1 - x0 + 1), np.uint8)
    for o in outlines:
        cv2.drawContours(mask, [(c - (x0, y0)).astype(np.int32) for c in o], -1, 255, -1)
    mask = cv2.dilate(mask, np.ones((5, 5), np.uint8))
    merged, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    return [c + np.int32([x0, y0]) for c in merged]


_NAME_LEAD = (r"(?:(?:bare|the|a|wooden|wood|light|dark|brown|grey|gray|white|black|plain|empty|flat|"
              r"blue|green|gridded|grid|squared|floor|table|desk|left|right|human|person's|persons)\s+)*")
_SURFACE_NAME_RE = re.compile(
    rf"^{_NAME_LEAD}(?:surfaces?|backgrounds?|tables?|tabletops?|table top|floors?|flooring|ground|mats?|"
    r"desks?|countertops?|counters?|shadows?|gaps?|wood|wood grain|planks?|boards?|board surface|"
    r"grids?|grid lines?|grid ?mats?|cutting ?mats?|work ?surfaces?|workbench(?:es)?|backdrops?)$")
_HAND_NAME_RE = re.compile(
    rf"^{_NAME_LEAD}(?:hands?|arms?|fingers?|wrists?|thumbs?|palms?|persons?|humans?)$")
UNKNOWN_SURFACE_SHARE = 0.10    # an outline this big (of what Vision looks at) that the namer could not name


def is_surface_name(name) -> bool:
    """"surface", "wood grain", "floor": what lies around the objects."""
    return bool(_SURFACE_NAME_RE.match(clean_object_name(name)))


def is_hand_name(name) -> bool:
    """"hand", "left hand": a person's, never a "hand brush"."""
    return bool(_HAND_NAME_RE.match(clean_object_name(name)))


def ignored_outlines(snap, namer):
    """(surface, hands): the indices of the outlines HOS X plans around but never
    with -- bare table the outliner traced, a hand holding something, and an
    outline as big as a tenth of the board that the namer could not name."""
    objects, ids = snap["objects"], snap["ids"]
    region = snap.get("region") or snap.get("box")
    frame = snap.get("frame")
    if region is not None:
        total = max(1.0, (region[2] - region[0]) * (region[3] - region[1]))
    else:
        total = float(frame.shape[0] * frame.shape[1]) if frame is not None else 0.0
    parents = snap.get("parents") or [None] * len(ids)
    table, hands = set(), set()
    for i, tid in enumerate(ids):
        name = namer.names.get(tid)
        if name and is_hand_name(name):
            hands.add(i)
        elif name and is_surface_name(name):
            table.add(i)
        elif (not name and tid in namer.asked and total
              and object_area(objects[i]) >= UNKNOWN_SURFACE_SHARE * total):
            table.add(i)
    gone = table | hands
    surface = set()
    for i in table:
        # a "floor" or "wall" the namer called a piece of a bigger thing (a
        # dustpan's), or that lies in a real object, is that thing's part,
        # never the table; one lying in a hand is still the table
        thing = str((namer.info.get(ids[i]) or {}).get("thing") or "").strip()
        p, seen = parents[i], 0
        while p is not None and p in gone and seen < len(parents):
            p, seen = parents[p], seen + 1
        if not thing and p is None:
            surface.add(i)
    return surface, hands


def _kept_parents(parents, skipped):
    """`parents` with every skipped outline stepped over: a part of a plank is
    a part of whatever the plank itself lies in, or of nothing."""
    out = list(parents)
    for i, p in enumerate(parents):
        seen = 0
        while p is not None and p in skipped and seen < len(parents):
            p, seen = parents[p], seen + 1
        out[i] = p
    return out


def cut_out(contours, cuts):
    """`contours` with the area of the `cuts` outlines taken out (a hand over
    a brush's handle): the pieces that are left. Unchanged when the cut barely
    touches it or would leave next to nothing (then it is the cut itself)."""
    x1, y1, x2, y2 = object_bbox(contours)
    mask = np.zeros((y2 - y1 + 1, x2 - x1 + 1), np.uint8)
    cv2.drawContours(mask, [(c - (x1, y1)).astype(np.int32) for c in contours], -1, 255, -1)
    area = int(np.count_nonzero(mask))
    cut = np.zeros_like(mask)
    hit = False
    for other in cuts:
        ox1, oy1, ox2, oy2 = object_bbox(other)
        if ox2 < x1 or ox1 > x2 or oy2 < y1 or oy1 > y2:
            continue
        cv2.drawContours(cut, [(c - (x1, y1)).astype(np.int32) for c in other], -1, 255, -1)
        hit = True
    if not hit or area == 0:
        return contours
    left = cv2.bitwise_and(mask, cv2.bitwise_not(cut))
    kept = int(np.count_nonzero(left))
    if area - kept < 0.03 * area or kept < 0.25 * area:
        return contours
    left = cv2.morphologyEx(left, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    pieces, _ = cv2.findContours(left, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    pieces = [p for p in pieces if cv2.contourArea(p) >= 0.02 * area]
    if not pieces:
        return contours
    return [p + np.int32([x1, y1]) for p in pieces]


LEAK_MIN_SHARE = 0.02       # a leak is a lump of at least this share of the outline's area...
LEAK_KEEP_MIN = 0.55        # ...and the outline keeps at least this share of it
LEAK_SIDE_PX = 256          # the work is done on a crop this big
CLEAN_MIN_SHARE = 0.004     # smaller outlines (of the frame) are left as FastSAM drew them


def _mask_in(contours, shape, off, scale):
    m = np.zeros(shape, np.uint8)
    cv2.drawContours(m, [((c.astype(np.float32) - off) * scale).astype(np.int32)
                         for c in contours], -1, 255, -1)
    return m


def trim_leaks(frame, contours, others=()):
    """The outline with the table taken out of it. FastSAM's mask sometimes
    runs out across a strip of the table beside an object (a white shirt's mask
    taking in the dark planks at its side), and the shape read from it is then
    the shirt AND the planks. Pixels inside the mask that look like the table
    around the object and not like the object, lying in a lump on the mask's
    edge, are cut off. `others` are outlines of other things, kept out of the
    sample of the table. Unchanged when the object looks like the table (they
    cannot be told apart), or when most of it would go."""
    x1, y1, x2, y2 = object_bbox(contours)
    pad = max(10, int(0.12 * max(x2 - x1, y2 - y1)))
    height, width = frame.shape[:2]
    X1, Y1 = max(0, x1 - pad), max(0, y1 - pad)
    X2, Y2 = min(width, x2 + pad + 1), min(height, y2 + pad + 1)
    if X2 - X1 < 20 or Y2 - Y1 < 20:
        return contours
    scale = min(1.0, LEAK_SIDE_PX / float(max(X2 - X1, Y2 - Y1)))
    crop = frame[Y1:Y2, X1:X2]
    small = (cv2.resize(crop, None, fx=scale, fy=scale, interpolation=cv2.INTER_AREA)
             if scale < 1 else crop)
    lab = cv2.cvtColor(small, cv2.COLOR_BGR2LAB).astype(np.float32)
    off = np.float32([X1, Y1])
    mask = _mask_in(contours, small.shape[:2], off, scale)
    area = int(np.count_nonzero(mask))
    if area < 300:
        return contours
    r = max(2, int(0.04 * max(mask.shape)))
    ring = (cv2.dilate(mask, np.ones((3 * r, 3 * r), np.uint8))
            & ~cv2.dilate(mask, np.ones((r, r), np.uint8)))
    for other in others:
        ring &= ~_mask_in(other, small.shape[:2], off, scale)
    inside, around = mask > 0, ring > 0
    if np.count_nonzero(around) < 150:
        return contours
    table = np.median(lab[around], axis=0)
    thing = np.median(lab[inside], axis=0)
    for _ in range(2):          # the colour of the part of it that is NOT table-like
        near_thing = inside & (np.linalg.norm(lab - thing, axis=2) < np.linalg.norm(lab - table, axis=2))
        if np.count_nonzero(near_thing) < 0.3 * area:
            break
        thing = np.median(lab[near_thing], axis=0)
    gap = float(np.linalg.norm(thing - table))
    if gap < 22:
        return contours
    d_thing = np.linalg.norm(lab - thing, axis=2)
    d_table = np.linalg.norm(lab - table, axis=2)
    leak = (inside & (d_table < 0.6 * d_thing) & (d_thing > 0.4 * gap)).astype(np.uint8) * 255
    leak = cv2.morphologyEx(leak, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n, labels, stats, _ = cv2.connectedComponentsWithStats(leak, connectivity=8)
    edge = inside & ~(cv2.erode(mask, np.ones((5, 5), np.uint8)) > 0)
    drop = np.zeros_like(mask)
    for k in range(1, n):
        if stats[k, cv2.CC_STAT_AREA] >= LEAK_MIN_SHARE * area and edge[labels == k].any():
            drop[labels == k] = 255
    if not drop.any():
        return contours
    left = cv2.bitwise_and(mask, cv2.bitwise_not(cv2.dilate(drop, np.ones((3, 3), np.uint8))))
    left = cv2.morphologyEx(left, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
    n, labels, stats, _ = cv2.connectedComponentsWithStats(left, connectivity=8)
    if n <= 1:
        return contours
    biggest = int(stats[1:, cv2.CC_STAT_AREA].max())
    keep = np.zeros_like(left)
    for k in range(1, n):
        if stats[k, cv2.CC_STAT_AREA] >= 0.08 * biggest:
            keep[labels == k] = 255
    if np.count_nonzero(keep) < LEAK_KEEP_MIN * area:
        return contours
    found, _ = cv2.findContours(keep, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    out = [(c.astype(np.float32) / scale + off).round().astype(np.int32)
           for c in found if len(c) >= 3]
    return out or contours


def clean_outlines(objects, parents, skipped, frame, is_robot):
    """The outlines with the table taken out of every top-level object's mask."""
    if frame is None:
        return objects
    total = float(frame.shape[0] * frame.shape[1])
    out = list(objects)

    def inside(j, i):
        seen = 0
        while j is not None and seen < len(parents):
            if j == i:
                return True
            j, seen = parents[j], seen + 1
        return False

    for i, contours in enumerate(objects):
        if (i in skipped or parents[i] is not None or is_robot(i)
                or object_area(contours) < CLEAN_MIN_SHARE * total):
            continue
        others = [objects[j] for j in range(len(objects))
                  if j != i and j not in skipped and not inside(j, i)]
        try:
            out[i] = trim_leaks(frame, contours, others)
        except Exception as e:
            print(f"[vision] outline cleanup skipped for #{i + 1}: {e}")
    return out


def planner_objects(snap, namer, grid: Grid):
    """A Vision AI snapshot as the planner's object list.

    Every outline keeps its tracked name. An outline inside a bigger one is
    one of that object's COMPONENTS -- unless the namer said it is a loose
    thing lying on it (a sock in a bowl), which makes it an object of its
    own, described as lying on the other. Robot parts are left out: they are
    equipment, not something on the board to plan with. `grid` is the grid
    box in the snapshot's own camera pixels.
    """
    objects, ids, parents = snap["objects"], snap["ids"], snap["parents"]
    frame = snap.get("frame")
    names, info = namer.names, namer.info
    cw, ch = cell_size_in(grid)
    surface, hands = ignored_outlines(snap, namer)
    skipped = surface | hands
    namer.left_out = {"hands": len(hands), "surface": len(surface)}
    if skipped:
        parents = _kept_parents(parents, skipped)
        if hands:
            cuts = [objects[h] for h in sorted(hands)]
            objects = [objects[i] if i in skipped else cut_out(objects[i], cuts)
                       for i in range(len(objects))]
        print("[vision] not planned with: " + ", ".join(
            f"#{i + 1} {'hand' if i in hands else 'surface'}" for i in sorted(skipped)))
    trimmed = clean_outlines(objects, parents, skipped, frame,
                             lambda i: bool((info.get(ids[i]) or {}).get("robot")))
    for i, (a, b) in enumerate(zip(objects, trimmed)):
        if a is not b:
            print(f"[vision] #{i + 1}: the table was cut out of its outline "
                  f"({object_area(a):.0f} -> {object_area(b):.0f} px)")
    objects = trimmed

    def meta(i):
        return info.get(ids[i]) or {}

    def foreign(i):
        """A part tagged as a piece of some OTHER thing than the object it
        lies on (the brush's handle lying in a dustpan) belongs to that
        thing, not to the dustpan - whatever its loose flag says."""
        t = str(meta(i).get("thing") or "").strip().lower()
        p = parents[i]
        if not t or p is None:
            return False
        host = (clean_object_name(names.get(ids[p])) or "",
                str(meta(p).get("thing") or "").strip().lower())
        return not any(h and (t in h or h in t) for h in host)

    def owner(i):
        """The object this outline belongs to: itself when it stands alone
        (or lies loose on something), else the nearest such ancestor."""
        seen = 0
        while (parents[i] is not None and not meta(i).get("loose")
               and not foreign(i) and seen < len(objects)):
            i, seen = parents[i], seen + 1
        return i

    entries, components = {}, {}
    for i, contours in enumerate(objects):
        if meta(i).get("robot") or i in skipped:
            continue
        poly = outline_polygon(contours, grid)
        if poly is None:
            continue
        cell, cells, pt = polygon_to_cells(poly)
        if cell is None:
            continue
        o = owner(i)
        name = clean_object_name(names.get(ids[i])) or (
            "part" if o != i else "unidentified object")
        entry = {"name": name, "center": coordinate_name(*cell),
                 "touches": ",".join(coordinate_name(*c) for c in cells),
                 "polygon": poly}
        set_center_pt(entry, pt)
        if o != i:
            xs, ys = [p[0] for p in poly], [p[1] for p in poly]
            w_in, h_in = (max(xs) - min(xs)) * cw, (max(ys) - min(ys)) * ch
            entry.update({
                "color": meta(i).get("color") or (
                    colour_word(object_color(frame, contours)) if frame is not None else "?"),
                "size": size_class(max(w_in, h_in)),
                "desc": meta(i).get("desc") or "",
            })
            entry["edge"] = edge_share(contours, objects[o])
            if TRAY_WORDS_RE.search(name) or LIP_WORDS_RE.search(name):
                entry["mouth"] = mouth_line(contours, objects[o], grid)
            components.setdefault(o, []).append(entry)
            continue
        colour = meta(i).get("color") or (
            colour_word(object_color(frame, contours)) if frame is not None else "?")
        xs, ys = [p[0] for p in poly], [p[1] for p in poly]
        w_in, h_in = (max(xs) - min(xs)) * cw, (max(ys) - min(ys)) * ch
        desc = meta(i).get("desc") or ""
        bits = [desc] if desc else []
        bits.append(f"about {w_in:.1f} x {h_in:.1f} in")
        if parents[i] is not None:
            under = names.get(ids[parents[i]])
            bits.append(f"lying on/in the {under}" if under else "lying on another object")
        entry.update({"color": colour, "size": size_class(max(w_in, h_in)),
                      "desc": ", ".join(bits), "aka": [], "components": [],
                      "track_id": ids[i]})
        if ids[i] not in names:
            entry["name_uncertain"] = True
        entries[i] = entry
    for o, comps in components.items():
        if o in entries:
            parent_poly = entries[o]["polygon"]
            entries[o]["components"] = [c for c in comps
                                        if component_on_parent(c["polygon"], parent_poly)]

    # Pieces of one thing (the namer's "thing"), touching: one object named
    # for the whole, its footprint all their cells, each piece a COMPONENT
    # with its own cells -- a hand brush's handle and bristles, a dustpan's
    # back wall, lip and floor, which FastSAM outlines separately.
    doubtful = set()
    for thing, members in thing_groups(
            list(entries), objects, lambda i: meta(i).get("thing"),
            frame.shape if frame is not None else None,
            name_of=lambda i: entries[i]["name"], doubtful=doubtful):
        merged = merge_outlines([objects[m] for m in members])
        poly = outline_polygon(merged, grid) if merged else None
        cell, cells, pt = polygon_to_cells(poly) if poly else (None, [], None)
        if cell is None:
            continue
        main = max(members, key=lambda m: object_area(objects[m]))
        pieces = []
        for m in sorted(members, key=lambda m: _reading_order(entries[m])):
            e = entries[m]
            # the piece named for the whole thing is its body
            piece = {"name": "body" if e["name"] == thing else e["name"],
                     "center": e["center"],
                     "touches": e["touches"], "polygon": e["polygon"],
                     "edge": edge_share(objects[m], merged)}
            for key in ("color", "size", "desc"):
                if e.get(key):
                    piece[key] = e[key]
            if TRAY_WORDS_RE.search(piece["name"]) or LIP_WORDS_RE.search(piece["name"]):
                piece["mouth"] = mouth_line(objects[m], merged, grid)
            if "center_pt" in e:
                piece["center_pt"] = e["center_pt"]
            pieces.append(piece)
            pieces.extend(e.get("components") or [])
        xs, ys = [q[0] for q in poly], [q[1] for q in poly]
        w_in, h_in = (max(xs) - min(xs)) * cw, (max(ys) - min(ys)) * ch
        whole = dict(entries[main])
        whole.update({
            "name": thing, "center": coordinate_name(*cell),
            "touches": ",".join(coordinate_name(*c) for c in cells),
            "polygon": poly, "size": size_class(max(w_in, h_in)),
            "desc": (f"seen as {len(members)} pieces ("
                     + ", ".join("body" if entries[m]["name"] == thing
                                 else entries[m]["name"] for m in members)
                     + f"), about {w_in:.1f} x {h_in:.1f} in"),
            "components": pieces})
        set_center_pt(whole, pt)
        for m in members:
            entries.pop(m, None)
        entries[main] = whole
        print(f"[vision] {thing}: joined {len(members)} pieces")
    for e in entries.values():
        note_opening(e)
    # A piece whose other pieces were not seen keeps its thing in its name;
    # one that only touches its thing (a floor line the namer took for the
    # brush's "neck") keeps its own name, flagged as a guess.
    for i, e in entries.items():
        thing = str(meta(i).get("thing") or "").strip().lower()
        if i in doubtful:
            e["name_uncertain"] = True
            e["desc"] = (f"{e.get('desc', '')}; only touches the {thing}, "
                         f"not one of its pieces").lstrip("; ")
        elif (thing and e.get("name") != thing and thing not in str(e.get("name"))
                and not str(e.get("desc", "")).startswith("seen as ")):
            e["name"] = f"{thing} {e['name']}"
    return [entries[i] for i in sorted(entries, key=lambda i: _reading_order(entries[i]))]


def _hint_matches(key: str, name: str) -> bool:
    """Whole-word match, never a raw substring.

    Plain `in` gave a folded "cloth" the parts of a "clothes dryer" -- door,
    drum, lint filter -- because "cloth" sits inside "clothes". A match that
    fires on the wrong object is worse than none: a "clothes dryer" would be
    folded like a towel.
    """
    if key == name:
        return True
    return re.search(rf"(?<!\w){re.escape(key)}(?!\w)", name) is not None


BOARD_WIDTH_IN = 24.0


VISION_FRAME_DIR_VAR = "HOSX_VISION_FRAME_DIR"


def save_vision_frame(raw_frame, grid):
    """Write the raw frame + grid box to HOSX_VISION_FRAME_DIR, if it is set.

    Returns the image path, or None when the dump is off or fails. Never
    raises: a diagnostic must not be able to break a vision run.
    """
    folder = os.environ.get(VISION_FRAME_DIR_VAR, "").strip()
    if not folder or raw_frame is None or grid is None:
        return None
    try:
        os.makedirs(folder, exist_ok=True)
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        path = os.path.join(folder, f"board_{stamp}.png")
        if not cv2.imwrite(path, raw_frame):
            return None
        h, w = raw_frame.shape[:2]
        with open(os.path.join(folder, f"board_{stamp}.json"), "w") as f:
            json.dump({"box": [float(v) for v in grid.box],
                       "square_cells": bool(grid.square_cells),
                       "n_cols": CONFIG.n_cols, "n_rows": CONFIG.n_rows,
                       "frame": [w, h]}, f)
        print(f"[vision] frame saved to {path}")
        return path
    except Exception as e:
        print(f"[vision] could not save the frame ({e})")
        return None


PLACEHOLDER_NAMES = frozenset((
    "object", "item", "thing", "unknown", "unidentified", "part", "piece",
    "device", "tool", "equipment", "stuff", "something", "n/a", "none",
))


def clean_object_name(raw) -> str:
    """A model's name field -> a usable object name, or "" if it is a refusal."""
    name = re.sub(r"\s+", " ", str(raw or "").strip().lower()).strip(" .,-")
    if not name or name in PLACEHOLDER_NAMES:
        return ""
    return name


def _clean_aka(raw, name: str):
    """Synonym list -> lowercase strings, minus the name itself and junk."""
    if isinstance(raw, str):
        raw = [raw]
    if not isinstance(raw, (list, tuple)):
        return []
    out = []
    for a in raw:
        a = re.sub(r"\s+", " ", str(a).strip().lower()).strip(" .,-")
        if a and a != name and a not in PLACEHOLDER_NAMES and a not in out:
            out.append(a)
    return out[:4]


QUALIFIER_WORDS = frozenset((
    "big", "large", "small", "little", "tiny", "long", "short", "tall",
    "wide", "narrow", "thick", "thin", "open", "closed", "empty", "full",
    "folded", "unfolded", "upright", "upside", "down", "left", "right",
    "upper", "lower", "top", "bottom", "near", "far", "first", "second",
    "black", "white", "grey", "gray", "red", "blue", "green", "yellow",
    "orange", "purple", "pink", "brown", "silver", "gold", "golden", "clear",
    "transparent", "dark", "light", "pale", "bright", "metal", "metallic",
    "plastic", "wooden", "wood", "glass", "steel", "chrome", "striped",
    "patterned", "plain", "old", "new", "dirty", "clean",
))


def _name_kind(name: str) -> str:
    """What an object IS, with the describing words taken off.

    "black sock", "white sock" and "sock" are all the same kind of thing, and
    an operator who says "the sock" means any of them. Grouping on the exact
    string instead misses that entirely: it only sees a clash when two names
    match character for character, so a board holding "sock", "sock" and
    "black sock" gets the first two renamed and the third left alone -- and
    the rename then falls back to cell numbers, because the colours that
    would have separated them were not all in the same group.
    """
    words = [w for w in re.split(r"[\s/_-]+", clean_object_name(name)) if w]
    kept = [w for w in words if w not in QUALIFIER_WORDS]
    return " ".join(kept) if kept else " ".join(words)


def _attr_values(objects, attr):
    """Each object's value for `attr`, or None if any is missing/useless."""
    vals = []
    for o in objects:
        v = re.sub(r"\s+", " ", str(o.get(attr) or "").strip().lower())
        v = v.strip(" .,-")
        if not v or v in {"?", "n/a", "none", "unknown", "mixed", "various"}:
            return None
        vals.append(v)
    return vals


def _separating_labels(group, kind):
    """Names that tell these same-kind objects apart, and how it was done.

    A describing word does not have to be UNIQUE to be worth using -- it only
    has to divide the group. Two black socks and two white ones is the normal
    case, and "black sock 1 / black sock 2 / white sock 1 / white sock 2" is
    a far better answer than numbering all four, because the operator can say
    "the white one" and cut the field in half. Requiring uniqueness threw
    colour away in exactly the case it helps most.
    """
    own = [clean_object_name(o.get("name")) for o in group]
    if all(own) and all(n != kind for n in own) and len(set(own)) >= 2:
        out = [""] * len(group)
        for val in set(own):
            idxs = [i for i, v in enumerate(own) if v == val]
            if len(idxs) == 1:
                out[idxs[0]] = val
                continue
            for rank, i in enumerate(sorted(idxs,
                                            key=lambda j: _reading_order(group[j])),
                                     start=1):
                out[i] = f"{val} {rank}"
        return out, "their own names then position"
    for attr, tag in (("color", "colour"), ("size", "size")):
        vals = _attr_values(group, attr)
        if not vals or len(set(vals)) < 2:
            continue
        labels = [f"{v} {kind}" for v in vals]
        if len(set(labels)) == len(labels):
            return labels, tag
        out = [""] * len(group)
        for val in set(vals):
            idxs = [i for i, v in enumerate(vals) if v == val]
            if len(idxs) == 1:
                out[idxs[0]] = f"{val} {kind}"
                continue
            for rank, i in enumerate(sorted(idxs,
                                            key=lambda j: _reading_order(group[j])),
                                     start=1):
                out[i] = f"{val} {kind} {rank}"
        return out, f"{tag} then position"

    shared = own[0] if all(own) and len(set(own)) == 1 else kind
    order = sorted(range(len(group)), key=lambda i: _reading_order(group[i]))
    labels = [""] * len(group)
    for rank, idx in enumerate(order, start=1):
        labels[idx] = f"{shared} {rank}"
    return labels, "position"


def disambiguate_names(objects):
    """Give objects of the same KIND something to tell them apart by.

    The planner resolves the operator's words against these names, so two
    entries the operator cannot address separately are two objects it will
    pick between at random -- and half the time it picks the wrong one.

    Three things this has to get right, all of which the exact-string version
    got wrong on a real board of four socks and an iron:

    - Group by KIND, not by string. "sock", "sock" and "black sock" are three
      socks. Matching strings saw only the first two.
    - Prefer a VISIBLE difference. Colour first, then size, then the object's
      own description -- something the operator can see and say. A cell
      reference is the last resort, because "the sock at C4" is not language
      anyone uses; it is the robot's coordinates handed back to the human.
    - Keep the shared word in `aka`, so "the sock" still matches all of them
      and the difference decides between them.
    """
    groups = {}
    for o in objects:
        kind = _name_kind(o.get("name"))
        if kind:
            groups.setdefault(kind, []).append(o)

    for kind, group in groups.items():
        if len(group) < 2:
            continue
        names = [clean_object_name(o.get("name")) for o in group]
        if len(set(names)) == len(names) and all(n != kind for n in names):
            continue

        labels, how = _separating_labels(group, kind)

        for o, label in zip(group, labels):
            aka = _clean_aka(o.get("aka"), label)
            old = clean_object_name(o.get("name"))
            for extra in (kind, old):
                if extra and extra != label and extra not in aka:
                    aka.insert(0, extra)
            o["name"] = label
            o["aka"] = aka[:4]
        print(f"[vision] {len(group)} objects of kind '{kind}' - "
              f"told apart by {how}")
    return objects


def _reading_order(obj):
    """(row, col) of an object's centre, for numbering left-to-right."""
    cell = parse_coordinate(str(obj.get("center") or "").strip())
    if cell is None:
        return (10 ** 6, 10 ** 6)
    return (cell[1], cell[0])


GRIPPER_AI = True


def _poly_span(poly):
    """(width, height) of a polygon's bounding box, in grid units."""
    xs = [p[0] for p in poly]
    ys = [p[1] for p in poly]
    return max(xs) - min(xs), max(ys) - min(ys)


